// Obtener el mensaje principal
const message = items[0].json.body;

// Texto del mensaje
const content = message.content || "";

// Adjuntos
const attachments = message.attachments || [];

// Regex → generar URL interna
function makeInternal(url) {
  if (!url) return url;

  return url.replace(
    /^https:\/\/([a-zA-Z0-9\-]+)\.ocm\.aigentss\.cloud/,
    'http://$1.ocm.aigentss.cloud:3000'
  );
}

// ------------------------------------
// Procesar TODOS los attachments
// ------------------------------------
const processedAttachments = attachments.map(att => ({
  ...att,
  data_url_external: att.data_url || null,
  data_url_internal: makeInternal(att.data_url),
  thumb_url_external: att.thumb_url || null,
  thumb_url_internal: makeInternal(att.thumb_url)
}));

// ------------------------------------
// Detectar tipos presentes en el mensaje
// ------------------------------------
let type = "unknown";

// Caso: solo texto
if (attachments.length === 0 && content.trim() !== "") {
  type = "text";

// Caso: hay adjuntos
} else if (attachments.length > 0) {

  // Si TODOS son imágenes
  if (attachments.every(a => a.file_type === "image")) {
    type = content.trim() !== "" ? "image_with_text" : "image";
  }

  // Si TODOS son audios
  else if (attachments.every(a => a.file_type === "audio")) {
    type = "audio";

  // Si TODOS son location
  } else if (attachments.every(a => a.file_type === "location")) {
    type = "location";

  // Mezcla de adjuntos → híbrido
  } else {
    type = "mixed";
  }
}

return [
  {
    json: {
      type,
      content_text: content,
      attachments: processedAttachments,
      raw: items[0].json
    }
  }
];

const node = items[0].json;
const editFields = $('Edit Fields').item.json;

// Extraer coordenadas del attachment
const attachment = node.attachments?.[0] || {};
const lat = attachment.coordinates_lat || null;
const lon = attachment.coordinates_long || null;

// Construir el content_text para el siguiente nodo
//const content = {
//  lat,
//  lon
//};
const content = `${lat}, ${lon}`;

let result = {
  type: node.type,
  content: content,   // aquí va listo para el agente
  raw: editFields
};

return [{ json: result }];

const out = [];

for (const item of $input.all()) {
  const type = item.json.type;

  if (type === "text" || type === "image_with_text") {
    out.push({
      json: {
        content: item.json.content_text,
        type: "text"
      }
    });
  } else {
    out.push(item);
  }
}

return out;

const input = ($input.first() && $input.first().json) || (items[0] && items[0].json) || {};
let editFields = {};
try {
  editFields = $('Edit Fields').first().json || {};
} catch (e) {
  editFields = input.raw || {};
}

const result = {
  type: input.type || 'unknown',
  content_text: input.content_text ?? input.content ?? '',
  raw: editFields,
};

return [{ json: result }];

function _qlNormalizeInitialCta(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}
function _qlInitialCtaDiscoveryText() {
  let marca = '';
  let modelo = '';
  try {
    const attrs = $('Get Context Contact').first().json?.contact?.additional_attributes || {};
    marca = String(attrs.marca || '').toUpperCase();
    modelo = String(attrs.modelo || '').trim();
  } catch (e) {}
  if (!marca) { try { marca = String($('Set Contact Context').first().json?.contact_context?.additional_attributes?.marca || '').toUpperCase(); } catch (e) {} }
  const marcaLabel = marca === 'HYUNDAI' ? 'Hyundai' : marca === 'KIA' ? 'KIA' : marca;
  const vehiculo = [marcaLabel, modelo].filter(Boolean).join(' ') || 'tu vehículo';
  return '¡Perfecto! Para orientarte mejor: ¿te interesa más la seguridad de ' + vehiculo + ', el control desde la app o revisar valores de activación?';
}
function _qlIsInitialCtaAffirmative() {
  let msg = '';
  let state = '';
  try { msg = $('Set Contact Context').first().json?.concat_message || ''; } catch (e) {}
  try { state = $('[MEM-1] Load Lead Memory').first().json?.conversation_state || ''; } catch (e) {}
  const n = _qlNormalizeInitialCta(msg).replace(/[.,!?]+/g, '').replace(/\s+/g, ' ');
  const allowedStates = new Set(['CONTACTED_1','CONTACTED_2','CONTACTED_3']);
  const allowedMsgs = new Set(['si','si enviarme informacion','si enviar informacion','si quiero conocerlas','si quiero conocer','si enviarlo','si muestrame las opciones','si muestreme las opciones','si compartir guia','si cuentame mas']);
  return allowedStates.has(String(state || '').toUpperCase()) && allowedMsgs.has(n);
}
if (_qlIsInitialCtaAffirmative()) {
  return [{ json: { indx: 0, sms: _qlInitialCtaDiscoveryText(), url: '', hasUrl: false, initial_cta_guard: true } }];
}

// ============================================================
// VALIDADOR DE PRECIOS / AISLAMIENTO DE MARCA (regla 0C, prompt v5.2+)
// El LLM NO debe escribir cifras de dinero ni datos de otra marca.
// Aquí limpiamos cualquier monto que el modelo haya emitido por error;
// los precios reales los inserta el bloque determinístico (show_price).
// ============================================================
const msgs = ($json.output && $json.output.messages) || [];

// Marca del lead (best-effort, tolerante a que no exista)
// FIX v5.17 (2026-07-21) - leer additional_attributes antes del guard final.
function normalizeBrandGuard(value) {
  const m = String(value || '').trim().toUpperCase();
  return (m === 'KIA' || m === 'HYUNDAI') ? m : '';
}
function resolveBrandGuard() {
  const directCandidates = [
    $json.marca,
    $json.contact_context?.additional_attributes?.marca,
    $json.contact_context?.custom_attributes?.marca,
    $json.contact_context?.marca,
    $json.contact_context?.lead?.marca,
    $json.conversation?.custom_attributes?.marca,
  ];
  for (const value of directCandidates) {
    const m = normalizeBrandGuard(value);
    if (m) return m;
  }
  try {
    const contact = $('Get Context Contact').first().json?.contact || {};
    const m = normalizeBrandGuard(contact.additional_attributes?.marca || contact.custom_attributes?.marca || contact.marca);
    if (m) return m;
  } catch (e) {}
  try {
    const ctx = $('Set Contact Context').first().json || {};
    const m = normalizeBrandGuard(ctx.contact_context?.additional_attributes?.marca || ctx.contact_context?.custom_attributes?.marca || ctx.marca);
    if (m) return m;
  } catch (e) {}
  try {
    const ef = $('Edit Fields').first().json || {};
    const m = normalizeBrandGuard(ef.marca || ef.body?.conversation?.meta?.sender?.additional_attributes?.marca || ef.body?.conversation?.custom_attributes?.marca);
    if (m) return m;
  } catch (e) {}
  return '';
}
let marca = resolveBrandGuard();

function isMoneyLine(ln) {
  if (/\d{3,4}[.,]\d{2}(?!\d)/.test(ln)) return true;          // 484.15, 520.00, 1134.60
  if (/(\$|💵|usd)\s*\d/i.test(ln)) return true;               // $520, 💵 520
  if (/^\s*•?\s*\d+\s*a(ñ|n)os?\s*:/i.test(ln)) return true;   // "• 1 año: ..."
  if (/^\s*📌.*(plan|telemetr|hyundai\s*link)/i.test(ln)) return true; // cabecera de tabla
  return false;
}
function stripMoney(text) {
  if (!text) return text;
  const kept = String(text).split(/\n/).filter(ln => !isMoneyLine(ln));
  return kept.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}
function fixBrand(text) {
  if (!text || !marca) return text;
  if (marca.indexOf('HYUNDAI') >= 0)
    return text.replace(/telemetr[ií]a\s*kia/gi, 'My Hyundai Link').replace(/\bKIA\b/g, 'Hyundai');
  if (marca.indexOf('KIA') >= 0)
    return text.replace(/my\s*hyundai\s*link/gi, 'Telemetría KIA').replace(/\bHYUNDAI\b/g, 'KIA');
  return text;
}

// R1 (2026-07-16): invariante "no prometer sin entregar".
// D2 de la ejecución 76974: el LLM redactó una PREGUNTA DE PERMISO
// ("¿Desea que le comparta las opciones?") en un turno cuya entrega ya era
// determinística (show_price=true) y el guard viejo la dejaba pasar
// (excluía preguntas y no cubría el subjuntivo "comparta").
function _qlPricingTermsR1(t) {
  return /(valores|planes|precios|opciones|pdf|propuesta|cotizacion)/.test(t);
}
function asksPricingPermission(text) {
  const raw = String(text || '');
  if (!/[¿?]/.test(raw)) return false;
  const t = raw.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (!_qlPricingTermsR1(t)) return false;
  return /\b(compart\w*|envi\w*|mand\w*|muestr\w*|mostr\w*|dej\w*|adjunt\w*|pas\w*)\b/.test(t);
}
function promisesPricingDelivery(text) {
  const raw = String(text || '');
  const t = raw.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (asksPricingPermission(raw) || !_qlPricingTermsR1(t)) return false;
  return /\b(compart\w*|envi\w*|mand\w*|muestr\w*|mostr\w*|dej\w*|adjunt\w*|pas\w*)\b/.test(t);
}
function shouldSuppressPricingOffer(text) {
  return asksPricingPermission(text) || promisesPricingDelivery(text);
}
function sanitizePricingOffer(text) {
  const raw = String(text || '').trim();
  if (!raw) return { publicText: '', suppressedText: '' };
  const parts = raw.match(/¿[^?]*\?|[^.!?¿]+(?:[.!?]+|$)/g) || [raw];
  const publicParts = [];
  const suppressedParts = [];
  for (const part of parts) {
    const clean = String(part || '').trim();
    if (!clean) continue;
    if (shouldSuppressPricingOffer(clean)) suppressedParts.push(clean);
    else publicParts.push(clean);
  }
  return {
    publicText: publicParts.join(' ').trim(),
    suppressedText: suppressedParts.join(' ').trim(),
  };
}
let pricingWillBeSent = $json.output?.show_price === true || $json.is_show_price === true;
try {
  // En la rama semántica $json es el output crudo del LLM (show_price puede
  // venir false); la decisión autoritativa vive en Check Handoff o Perdida.
  const _chk = $('Check Handoff o Perdida').first().json || {};
  if (_chk.is_show_price === true || _chk.output?.show_price === true) pricingWillBeSent = true;
} catch (e) {}
if (pricingWillBeSent && msgs.length > 0 && msgs.every(m => shouldSuppressPricingOffer(m.sms || ''))) {
  // Turno con entrega determinística: el menú/PDF de CSE — Send Pricing ES la
  // respuesta. Suprimir promesas y preguntas de permiso del LLM.
  return [];
}
function isPrePricingAffirmativeHandoff() {
  let msg = '';
  let state = '';
  let lastType = '';
  let selectedPlan = '';
  try { msg = $('Set Contact Context').first().json?.concat_message || ''; } catch (e) {}
  try {
    const mem = $('[MEM-1] Load Lead Memory').first().json || {};
    state = String(mem.conversation_state || '').toUpperCase();
    lastType = String(mem.last_response_type || '').toUpperCase();
    selectedPlan = String(mem.selected_plan || '');
  } catch (e) {}
  const n = _qlNormalizeInitialCta(msg).replace(/[.,!?]+/g, '').replace(/\s+/g, ' ');
  const affirmative = /^(si|sí|claro|ok|dale|correcto|adelante|por favor)$/.test(n);
  const prePricingState = ['VALUE_PRESENTED','ENGAGED','OBJECTION'].includes(state);
  const pricingAlreadySent = ['PRICE_PRESENTED','PRICING_PRESENTED'].includes(lastType) || Boolean(selectedPlan);
  return affirmative && prePricingState && !pricingAlreadySent && $json.output?.trigger_handoff === true;
}
if (isPrePricingAffirmativeHandoff()) {
  return [];
}

// R1b (2026-07-16): pregunta de permiso de precios SIN entrega en el turno
// -> desaparece del canal público y se registra como NOTA PRIVADA en Chatwoot.
// Caso reportado: "¿Desea que le comparta nuevamente las opciones y valores...?"
const _suppressedPermissionMsgs = [];
let _publicMsgs = msgs;
let _allowQ2PricePermission = false;
try {
  const _check = $('Check Handoff o Perdida').first().json || {};
  _allowQ2PricePermission = _check.q2_pricing_policy === 'ASK_PERMISSION'
    && ['seguridad', 'control'].includes(String(_check.gancho_q2_choice || '').toLowerCase())
    && String(_check.last_response_type || _check.output?.last_response_type || '').toUpperCase() === 'PRICE_PERMISSION_ASKED';
} catch (e) {}
if (!pricingWillBeSent && !_allowQ2PricePermission) {
  _publicMsgs = [];
  for (const m of msgs) {
    const _text = String(m.sms || '');
    if (!shouldSuppressPricingOffer(_text)) {
      _publicMsgs.push(m);
      continue;
    }
    const _cleaned = sanitizePricingOffer(_text);
    if (_cleaned.suppressedText) {
      _suppressedPermissionMsgs.push({ ...m, sms: _cleaned.suppressedText });
    }
    if (_cleaned.publicText) {
      _publicMsgs.push({ ...m, sms: _cleaned.publicText });
    } else if (m.url) {
      _publicMsgs.push({ ...m, sms: '' });
    }
  }
}
if (_suppressedPermissionMsgs.length) {
  try {
    const _ef = $('Edit Fields').first().json;
    if (_ef.URL_OMNICEM && _ef.TOKEN && _ef.account_id && _ef.conversation_display_id) {
      const _note = [
        '🔒 CRIS — pregunta de permiso de precios SUPRIMIDA (no enviada al cliente):',
        '',
        ..._suppressedPermissionMsgs.map(m => '«' + String(m.sms || '').trim() + '»'),
        '',
        'Motivo: el turno no entrega precios (show_price=false); ofrecer re-compartir sin entregar genera fricción/promesas colgadas.',
        'Regla R1b — docs/RCA-REOPEN-PRICING-2026-07-16.md'
      ].join('\n');
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://' + _ef.URL_OMNICEM + '/api/v1/accounts/' + _ef.account_id + '/conversations/' + _ef.conversation_display_id + '/messages',
        headers: { api_access_token: _ef.TOKEN, 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: _note, message_type: 1, private: true })
      }).catch(() => null);
    }
  } catch (e) {}
}

function normalizeOutboundUrl(raw) {
  const value = String(raw || '').trim();
  if (!value) return '';
  let url = value;
  if (/^url_del_pdf_de_propuesta_kia$/i.test(value)) url = 'https://codercase.com/img/QL/PROPUESTA_COMERCIAL_KIA.pdf';
  if (/^url_del_pdf_de_propuesta_hyundai$/i.test(value)) url = 'https://codercase.com/img/QL/PROPUESTA_COMERCIAL_HYUNDAI.pdf';
  if (!/^https?:\/\//i.test(url)) return '';
  if (pricingWillBeSent && /\.pdf(?:\?|$)/i.test(url)) return '';
  return url;
}

const outboundMsgs = _publicMsgs.map((m, i) => {
  const sms = fixBrand(stripMoney(m.sms || ""));
  const url = normalizeOutboundUrl(m.url || "");
  return { indx: i, sms, url, hasUrl: Boolean(url) };
}).filter(x => (x.sms && x.sms.trim() !== "") || x.hasUrl)
  .map((x, i) => ({ ...x, indx: i }));

if (outboundMsgs.length === 0 && _publicMsgs.length > 0) {
  const fallbackText = fixBrand(String(_publicMsgs.map(m => m.sms || '').find(Boolean) || '').trim());
  if (fallbackText) return [{ json: { indx: 0, sms: fallbackText, url: '', hasUrl: false, empty_turn_guard: true } }];
}

return outboundMsgs.map(json => ({ json }));

