={{ $('Concatenar Buffer').item.json.system_promt + (function(){
  try {
    const mem = $('[MEM-1] Load Lead Memory').item?.json;
    if (!mem || !mem.conversation_state || mem.conversation_state === 'NEW_LEAD') return '';
    let block = '\n[MEMORIA ACTIVA]\n';
    block += 'estado_conversacion: ' + mem.conversation_state + '\n';
    block += 'turno: ' + (mem.turn_count || 0) + '\n';
    if (mem.gps_previo) block += 'experiencia_gps: ' + mem.gps_previo + ' (respondida)\n';
    if (mem.problema_principal) block += 'problema_principal: ' + mem.problema_principal + ' (respondida)\n';
    if (mem.decision_maker) block += 'tomador_decision: ' + mem.decision_maker + ' (respondida)\n';
    try {
      if (mem.summary && String(mem.summary).startsWith('{')) {
        const cp = JSON.parse(mem.summary);
        if (cp.urgencia) block += 'urgencia: ' + cp.urgencia + ' (respondida)\n';
        block += 'calificacion_json: ' + mem.summary + '\n';
      } else if (mem.summary) block += 'resumen: ' + mem.summary + '\n';
    } catch(e) {}
    if (mem.ultima_pregunta_campo) block += 'siguiente_pregunta_campo: ' + mem.ultima_pregunta_campo + '\n';
    block += 'REGLA: NUNCA repita una pregunta cuyo campo ya figure como respondida arriba.\n';
    block += '[/MEMORIA ACTIVA]\n';
    return block;
  } catch(e) { return ''; }
})() + (function(){
  try {
    const contact = $('Get Context Contact').item?.json?.contact;
    const attrs = contact?.additional_attributes || {};
    let marca = String(attrs.marca || '').toUpperCase();
    let modelo = String(attrs.modelo || '').trim();
    if (!marca || !modelo) {
      const convAttrs = $('Get Context Contact').item?.json?.conversation?.custom_attributes || {};
      if (!marca) marca = String(convAttrs.marca || '').toUpperCase();
    }
    if (!marca && !modelo) return '';
    const marcaLabel = marca === 'HYUNDAI' ? 'Hyundai' : marca === 'KIA' ? 'KIA' : marca;
    const vehiculo = [marcaLabel, modelo].filter(Boolean).join(' ');
    const servicio = marca === 'HYUNDAI' ? 'My Hyundai Link' : marca === 'KIA' ? 'Telemetría KIA' : 'servicio de rastreo vehicular';
    let block = '\n[DATOS LEAD]\n';
    if (marca) block += 'marca: ' + marca + '\n';
    if (modelo) block += 'modelo: ' + modelo + '\n';
    if (vehiculo) block += 'vehiculo: ' + vehiculo + '\n';
    block += 'servicio: ' + servicio + '\n';
    block += 'REGLA: Use SIEMPRE "' + vehiculo + '" al referirse al vehículo. NUNCA mencionar otra marca (Toyota, Nissan, etc.).\n';
    block += '[/DATOS LEAD]\n';
    return block;
  } catch(e) { return ''; }
})() }}

