const out = { ...$json };

// Asegura existencia de la estructura
out.contact_context = out.contact_context || {};
out.contact_context.custom_attributes = out.contact_context.custom_attributes || {};

// Setea SOLO el atributo necesario
out.contact_context.custom_attributes.terms_accepted = true;
out.contact_context.custom_attributes.terms_accepted_at =
out.contact_context.custom_attributes.terms_accepted_at ?? new Date().toISOString();
out.contact_context.tac = true;
out.contact_context.tac_accepted_at =
out.contact_context.tac_accepted_at ?? new Date().toISOString();

return [{ json: out }];

const concat = String($json.concat_message ?? '');
const pending = String($json.pending_intent_block ?? '');
const contact = $json.contact_context ?? {};
const convo = $json.conversation ?? {};

const content =
`User Message: ${concat}`;

const memoryObj = {
  type: "human",
  content,
  additional_kwargs: {},
  response_metadata: {}
};

return [{
  json: {
    ...$json,
    memory_message_obj: memoryObj,
    memory_message_text: JSON.stringify(memoryObj) 
  }
}];

const senderType = String(
  $json.body?.conversation?.messages?.[0]?.sender_type || ''
).toLowerCase();

const isUserMessage =
  $json.body?.event === 'message_created' &&
  (senderType === 'contact' || senderType === 'user');

return [{
  json: {
    ...$json,
    is_user_message: isUserMessage,
    _debug: {
      event: $json.body?.event,
      sender_type: senderType
    }
  }
}];

// Version PDF filename so WhatsApp/Meta do not reuse cached document by name
const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
for (const item of $input.all()) {
  const bin = item.binary?.data;
  if (!bin) continue;
  const isPdf = (bin.mimeType || '').includes('pdf') || (bin.fileName || '').toLowerCase().endsWith('.pdf');
  if (!isPdf) continue;
  const base = (bin.fileName || 'Propuesta_Rastreo_Vehicular').replace(/\.pdf$/i, '');
  bin.fileName = `${base}_${stamp}.pdf`;
}
return $input.all();

const err = $json.error || {};
const errMessage = err.message || $json.message || 'AI parser failed';
let base = {};
try { base = $('[WIN-MERGE] Restore Context').first().json || {}; } catch (e) {}
if (!base || Object.keys(base).length === 0) {
  try { base = $('Edit Fields').first().json || {}; } catch (e) {}
}
const state = base.mem_state || base.conversation_state || $json.mem_state || $json.conversation_state || 'ENGAGED';
return [{
  json: {
    ...base,
    ...$json,
    output: {
      reply: {
        text: 'Gracias por tu mensaje. Estoy revisando la información para ayudarte mejor.',
        channel_hints: { attachments: [] }
      },
      next_state: state,
      trigger_handoff: false,
      trigger_loss: false,
      trigger_descuento_handoff: false,
      show_price: false,
      observacion_api: 'AI parser fallback'
    },
    next_state: state,
    trigger_handoff: false,
    trigger_loss: false,
    trigger_perdida: false,
    trigger_descuento_handoff: false,
    is_show_price: false,
    ai_parser_fallback: true,
    ai_parser_error: String(errMessage).slice(0, 300)
  }
}];

function stripAccents(s) {
  return String(s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalize(s) {
  return stripAccents(String(s || '').toLowerCase())
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const raw = $json.concat_message ?? '';
const msg = normalize(raw);

const negativePhrases = [
  'no acepto',
  'no autorizo',
  'no estoy de acuerdo',
  'no deseo continuar',
  'no quiero continuar',
  'me niego',
  'no doy permiso'
].map(normalize);

const negativeWords = [
  'rechazo',
  'deniego'
].map(normalize);

const isNegative =
  negativePhrases.some(p => (` ${msg} `).includes(` ${p} `)) ||
  negativeWords.some(w => msg.split(' ').includes(w));

const isEmpty = msg.length === 0;

return [{
  json: {
    ...$json,
    consent_eval: {
      raw,
      normalized: msg,
      is_negative: isNegative,
      is_empty: isEmpty,
      can_continue: !isNegative && !isEmpty
    }
  }
}];

async function __salesProdHttpRequest(opts) {
  if (opts && String(opts.url || '').includes('/rest/v1/')) {
    opts = {
      ...opts,
      headers: {
        ...(opts.headers || {}),
        'Accept-Profile': 'sales_prod',
        'Content-Profile': 'sales_prod',
      },
    };
  }
  return this.helpers.httpRequest(opts);
}

const _swallowed = [];
function _swallow(e, tag) {
  _swallowed.push({ tag, message: String((e && e.message) || e).slice(0, 300) });
  return null;
}

// GUARD v2.12 — bloquear pregunta cantidad vehículos
const VEHICULOS_PAT = /cu[aá]ntos?\s+veh[ií]culos?|cantidad\s+de\s+veh[ií]culos?|para\s+cu[aá]ntos?\s+veh/i;
const URGENCIA_Q = '¿En qué plazo estaría considerando tomar una decisión sobre este servicio?';
function stripVehiculosQuestion(text) {
  if (!text || !VEHICULOS_PAT.test(text)) return text;
  let cleaned = text
    .replace(/[^.?\n]*cu[aá]ntos?\s+veh[ií]culos?[^.?\n]*[.?\n]?/gi, '')
    .replace(/[^.?\n]*cantidad\s+de\s+veh[ií]culos?[^.?\n]*[.?\n]?/gi, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (!cleaned || cleaned.length < 15 || VEHICULOS_PAT.test(cleaned)) {
    cleaned = `Gracias por la información. ${URGENCIA_Q}`;
  } else if (!/plazo|decisi[oó]n|urgencia|considerando tomar/i.test(cleaned)) {
    cleaned = `${cleaned}\n\n${URGENCIA_Q}`;
  }
  return cleaned;
}
if ($json.output?.reply?.text) {
  $json.output.reply.text = stripVehiculosQuestion($json.output.reply.text);
}
if ($json.output?.calificacion_data?.campo_actualizado === 'cantidad_vehiculos') {
  $json.output.calificacion_data = { campo_actualizado: null, valor: null };
}
if ($json.output?.siguiente_pregunta_campo === 'cantidad_vehiculos') {
  $json.output.siguiente_pregunta_campo = 'urgencia';
  $json.output.siguiente_pregunta_texto = URGENCIA_Q;
  $json.output.siguiente_pregunta_orden = 4;
}

// [GATE Fase C] Rejection gate por estado de calificación
// mem_state viene de [MEM-1] + [CTX-MEM]
const QUALIFICATION_STATES = new Set(['ENGAGED','VALUE_PRESENTED','VEHICLE_SELECTION']);
const currentState  = $json.mem_state || $json.conversation_state || (() => { try { return $('[MEM-1] Load Lead Memory').first().json?.conversation_state; } catch (e) { return null; } })() || 'NUEVO_LEAD';
const inCalificacion = QUALIFICATION_STATES.has(String(currentState || '').toUpperCase());

// CRIS v2.5 — Output parser output is already an object; handle both cases
const outputRaw = $json.output;
let lower = '';
let rawOutput = '';
let ai = null;

if (outputRaw && typeof outputRaw === 'object') {
  // Structured output parser already deserialized — use directly
  ai = outputRaw;
  rawOutput = JSON.stringify(outputRaw);
  lower = rawOutput.toLowerCase();
} else {
  rawOutput = String(outputRaw || $json.text || '');
  lower = rawOutput.toLowerCase();
  try {
    const m = rawOutput.match(/```json\s*([\s\S]*?)```/) || rawOutput.match(/^(\{[\s\S]*\})\s*$/m);
    if (m) ai = JSON.parse(m[1]);
  } catch(e) { /* fallback a keywords */ }
}

// Fallback: fields at top-level of $json (legacy path)
if (!ai && typeof $json.next_state === 'string') {
  ai = {
    next_state: $json.next_state,
    trigger_handoff: $json.trigger_handoff,
    trigger_loss: $json.trigger_loss,
    trigger_descuento_handoff: $json.trigger_descuento_handoff,
    observacion_api: $json.observacion_api,
    show_price: $json.show_price,
    calificacion_data: $json.calificacion_data
  };
}

const nextState = ai?.next_state || null;
let triggerDescuento = ai?.trigger_descuento_handoff === true;

// Señales de CIERRE / HANDOFF (keywords fallback — solo si no hay AI estructurado)
const cierreKw = [
  'acepto','acepta','deseo contratar','quiero contratar',
  'quiero el plan','deseo el plan','como pago','como procedo',
  'cuando instalan','donde firmo','quiero hablar con',
  'comunicame con','hablar con un asesor',
  'vamos','adelante','procedamos','si lo quiero','si quiero'
];

// Señales de PERDIDA
const perdidaKw = [
  'no me interesa','no gracias','no deseo','no quiero',
  'ya tengo','muy caro','no tengo presupuesto','sin presupuesto',
  'no lo necesito','dejeme en paz','no moleste','no es para mi',
  'tengo seguro','poseo otro rastreo'
];

const wantsBuyKw = cierreKw.some(k => lower.includes(k));
const rejectedKw  = perdidaKw.some(k => lower.includes(k));

// GUARD v3.2 — handoff solo con trigger_handoff explícito (no por next_state stale)
const INTERES_CTA = /cu[eé]ntame m[aá]s|quiero saber m[aá]s|quiero m[aá]s informaci[oó]n|quiero descubrirlas|me interesa|quiero conocer|button_text|button_action/i;
let userMsg = '';
try {
  const ef = $('Edit Fields').first().json;
  userMsg = String(ef?.body?.content || ef?.body?.message || ef?.content || (() => { try { return $('Set Contact Context').first().json?.concat_message; } catch (e) { return ''; } })() || '').toLowerCase();
} catch (e) {}
const directUserMsg = userMsg;
const buttonSelectionMsg = [$json.button_guard_key, $json.button_guard_title].filter(Boolean).join(' ').toLowerCase();
if (buttonSelectionMsg) userMsg = (userMsg + ' ' + buttonSelectionMsg).trim();

const wantsBuy = ai
  ? (ai.trigger_handoff === true)
  : wantsBuyKw;

// Si el cliente solo muestra interés inicial, anular handoff aunque el LLM lo haya marcado
if (wantsBuy && INTERES_CTA.test(userMsg) && !/contrat|compr|pagar|firmar|proced|instal/i.test(userMsg)) {
  if ($json.output) {
    $json.output.trigger_handoff = false;
    if ($json.output.next_state === 'TRANSFERIDO_HUMANO') {
      $json.output.next_state = 'HANDOFF_HUMAN';
    }
  }
}

const ambiguousPositiveNo = /\bno\s*[,.;:]\s*(?:si\s*)?quiero\s+(?:saber|conocer|ver|recibir|cotizar|contratar|comprar|continuar|informaci[oó]n|opciones|planes|que\s+me\s+cuenten|m[aá]s)/i.test(userMsg);
if (ambiguousPositiveNo && $json.output) {
  $json.output.trigger_loss = false;
  $json.output.trigger_perdida = false;
  if ($json.output.next_state === 'LOST' || $json.output.next_state === 'OPORTUNIDAD_PERDIDA') $json.output.next_state = 'ENGAGED';
}

const rejected = !ambiguousPositiveNo && (inCalificacion
  // En calificación: solo aceptar trigger_loss EXPLÍCITO del LLM, nunca inferir por next_state ni keywords
  ? (ai?.trigger_loss === true)
  // Fuera de calificación: lógica original
  : (ai
      ? (nextState === 'OPORTUNIDAD_PERDIDA' || ai.trigger_loss === true)
      : rejectedKw));

// INTERESADO: solo cuando el AI lo indica explícitamente con next_state
const isInteresado = !wantsBuy && !rejected && nextState === 'INTERESADO';

// CALIFICACION: AI está guardando una respuesta de calificación
const isCalificacion = !wantsBuy && !rejected && nextState === 'CALIFICACION';

// Extraer calificacion_data del output estructurado del AI
let calificacionData = ai?.calificacion_data || null;

let observacion_api = ai?.observacion_api || null;
if (!observacion_api && rejected) {
  const l = lower;
  if (l.includes('precio') || l.includes('caro'))           observacion_api = 'Cliente rechaza por precio';
  else if (l.includes('presupuesto'))                        observacion_api = 'Cliente sin presupuesto';
  else if (l.includes('seguro'))                             observacion_api = 'Cliente adquirio seguro';
  else if (l.includes('rastreo') || l.includes('gps'))      observacion_api = 'Cliente posee otro rastreo';
  else if (l.includes('despues') || l.includes('posterior')) observacion_api = 'Cliente solicita contacto posterior';
  else                                                        observacion_api = 'Cliente no desea';
}

let memCommercial = {};
try { memCommercial = $('[MEM-1] Load Lead Memory').first().json || {}; } catch (e) {}

const normalizePlanText = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
function detectSelectedPlan(text) {
  const t = normalizePlanText(text);
  if (!t) return null;
  const payload = t.match(/\bplan_[a-z0-9_]+_(12|24|36)m\b/);
  if (payload) return Number(payload[1]);
  const onlyNumber = t.match(/^\s*([123])\s*$/);
  if (onlyNumber) return Number(onlyNumber[1]) * 12;
  const months = t.match(/\b(12|24|36)\s*mes(?:es)?\b/);
  if (months) return Number(months[1]);
  if (/\b(opcion\s*1|plan\s*1|primer\s+plan|la\s+primera|uno|1\s*ano|un\s+ano|de\s+un\s+ano|el\s+de\s+un\s+ano|anual)\b/.test(t)) return 12;
  if (/\b(opcion\s*2|plan\s*2|segundo\s+plan|la\s+segunda|dos|2\s*anos|dos\s+anos|de\s+dos\s+anos|el\s+de\s+dos\s+anos)\b/.test(t)) return 24;
  if (/\b(opcion\s*3|plan\s*3|tercer\s+plan|la\s+tercera|tres|3\s*anos|tres\s+anos|de\s+tres\s+anos|el\s+de\s+tres\s+anos)\b/.test(t)) return 36;
  return null;
}

function detectSelectedPlanCode(text) {
  const t = normalizePlanText(text);
  const payload = t.match(/\bplan_([a-z0-9_]+?)_(12|24|36)m\b/);
  return payload ? payload[1].toUpperCase() : null;
}

function durationHumanLabel(months) {
  const m = Number(months) || 0;
  if (m > 0 && m % 12 === 0) {
    const years = m / 12;
    return years === 1 ? '1 año' : years + ' años';
  }
  return m + ' meses';
}

const PLAN_MAP = {
  12: { code: 'PLAN_1_YEAR', duration: 12, tag: 'plan_1_year' },
  24: { code: 'PLAN_2_YEAR', duration: 24, tag: 'plan_2_year' },
  36: { code: 'PLAN_3_YEAR', duration: 36, tag: 'plan_3_year' },
};

const selectedPlanDurationDetected = detectSelectedPlan(userMsg);
const selectedPlanCodeHint = detectSelectedPlanCode(userMsg);
const selectionBrand = resolveMarcaFromContext(selectedPlanCodeHint);
const textualPlanLookupNeedsBrand = Boolean(selectedPlanDurationDetected && !selectionBrand);
const selectedPlanInfo = selectedPlanDurationDetected && selectionBrand ? PLAN_MAP[selectedPlanDurationDetected] : null;
let existingSelectedPlan = memCommercial.selected_plan || null;
let selectedPlanName = memCommercial.selected_plan_name || null;
let selectedPlanPrice = memCommercial.selected_plan_price || null;
let selectedPlanDuration = memCommercial.selected_plan_duration || null;
let planJustSelected = false;
let lastResponseType = null;

function resolveMarcaFromContext(codeHint = null) {
  let marca = String(
    $json.marca ||
    $json.contact_context?.additional_attributes?.marca ||
    $json.contact_context?.custom_attributes?.marca ||
    $json.conversation?.custom_attributes?.marca ||
    ''
  ).toUpperCase();
  if (!marca) {
    try {
      const ef = $('Edit Fields').first().json || {};
      marca = String(
        ef.marca ||
        ef.body?.conversation?.meta?.sender?.additional_attributes?.marca ||
        ef.body?.conversation?.custom_attributes?.marca ||
        ''
      ).toUpperCase();
    } catch(e) {}
  }
  if (!marca) {
    try { marca = String($('Get Context Contact').first().json?.contact?.additional_attributes?.marca || '').toUpperCase(); } catch(e) {}
  }
  if (!marca) {
    const brandByPlanCode = { TELEMETRIA: 'KIA', MY_HYUNDAI: 'HYUNDAI' };
    marca = brandByPlanCode[String(codeHint || '').toUpperCase()] || '';
  }
  if (!marca) {
    const text = normalizePlanText(
      (typeof directUserMsg !== 'undefined' && directUserMsg)
      || (typeof userMsg !== 'undefined' && userMsg)
      || ''
    );
    const mentioned = [
      /\bkia\b/.test(text) ? 'KIA' : null,
      /\bhyundai\b/.test(text) ? 'HYUNDAI' : null,
    ].filter(Boolean);
    if (mentioned.length === 1) marca = mentioned[0];
  }
  return (marca === 'KIA' || marca === 'HYUNDAI') ? marca : null;
}

async function loadPlanDetails(duration, codeHint) {
  const marca = resolveMarcaFromContext(codeHint);
  const serviceName = marca === 'HYUNDAI' ? 'My Hyundai Link' : marca === 'KIA' ? 'KIA Telemetría' : 'servicio de rastreo vehicular';
  const fallback = { name: serviceName, price: null, lookup_status: marca ? 'plan_not_found' : 'brand_missing' };
  if (!marca) return fallback;
  try {
    const SB_URL = ($env.RENOV_SUPABASE_REST_URL || 'http://127.0.0.1:9');
    const SB_KEY = $env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET';
    const MARCA_IDS = { KIA: 'e0604c9c-d124-43cf-99cf-2f84f37139d7', HYUNDAI: '54dda244-260c-440d-93ea-33a8aea7f49a' };
    const PLAN_CODES = { KIA: 'TELEMETRIA', HYUNDAI: 'MY_HYUNDAI' };
    const marcaId = MARCA_IDS[marca];
    const requestedCodes = [...new Set([codeHint, PLAN_CODES[marca], ''].filter(code => code !== null && code !== undefined))];
    if (!marcaId) return fallback;
    for (const requestedCode of requestedCodes) {
      const codeFilter = requestedCode ? '&codigo_plan=eq.' + encodeURIComponent(requestedCode) : '';
      const rows = await __salesProdHttpRequest.call(this, {
        method: 'GET',
        url: SB_URL + '/rest/v1/planes_marca?select=nombre_plan,meses,precio_usd,codigo_plan&activo=eq.true&marca_id=eq.' + marcaId + '&meses=eq.' + duration + codeFilter + '&order=meses.asc&limit=1',
        headers: { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY }
      });
      const p = Array.isArray(rows) ? rows[0] : null;
      if (p) return { name: p.nombre_plan || serviceName, price: p.precio_usd != null ? Number(p.precio_usd) : null };
    }
    return fallback;
  } catch(e) { return fallback; }
}

if (!existingSelectedPlan && selectedPlanInfo) {
  const details = await loadPlanDetails.call(this, selectedPlanInfo.duration, selectedPlanCodeHint);
  existingSelectedPlan = selectedPlanInfo.code;
  selectedPlanName = details.name;
  selectedPlanPrice = details.price;
  selectedPlanDuration = selectedPlanInfo.duration;
  planJustSelected = true;
  lastResponseType = 'PLAN_SELECTED';

  const yearsLabel = durationHumanLabel(selectedPlanInfo.duration);
  const priceLine = selectedPlanPrice != null ? '✅ Valor: ' + Number(selectedPlanPrice).toFixed(2) + ' USD' : null;
  if ($json.output) {
    $json.output.reply = $json.output.reply || { text: '', channel_hints: { attachments: [] } };
    $json.output.reply.text = [
      'Excelente elección 👍',
      '',
      'Plan seleccionado:',
      '✅ ' + (selectedPlanName || 'opción seleccionada'),
      '✅ ' + yearsLabel,
      priceLine,
      '',
      'Para coordinar la instalación y activación del servicio, uno de nuestros asesores especializados se comunicará con usted.',
      '',
      '¿Desea que lo contacten por WhatsApp o llamada?'
    ].filter(Boolean).join('\n');
    $json.output.next_state = 'PLAN_SELECTED';
    $json.output.trigger_handoff = false;
    $json.output.show_price = false;
  }

  try {
    const ef = $('Edit Fields').first().json;
    const urlBase = ef.URL_OMNICEM;
    const token = ef.TOKEN || $env.RENOV_CHATWOOT_API_TOKEN || '';
    const accountId = ef.account_id;
    const chatwootConvId = ef.conversation_display_id;
    if (urlBase && token && accountId && chatwootConvId) {
      // WF-09 TagManager owns Chatwoot labels; selected_plan is persisted below.
      let ctxContactAttrs = {};
      let ctxConversationAttrs = {};
      try {
        const ctx = $('Get Context Contact').first().json || {};
        ctxContactAttrs = ctx.contact?.additional_attributes || {};
        ctxConversationAttrs = ctx.conversation?.custom_attributes || {};
      } catch(e) {}

      const contactAttrs = $json.contact_context?.additional_attributes || {};
      const contactCustomAttrs = $json.contact_context?.custom_attributes || {};
      const conversationAttrs = $json.conversation?.custom_attributes || {};
      let activeVehicleAttrs = {};
      let dbLeadAttrs = {};

      try {
        const SB_URL_NOTE = ($env.RENOV_SUPABASE_REST_URL || 'http://127.0.0.1:9');
        const SB_KEY_NOTE = $env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET';
        const H_NOTE = { apikey: SB_KEY_NOTE, Authorization: 'Bearer ' + SB_KEY_NOTE };
        const cwId = parseInt(chatwootConvId || $json.conversation?.id || $json.conversation?.display_id, 10) || 0;
        if (cwId) {
          const ctxRows = await __salesProdHttpRequest.call(this, {
            method: 'GET',
            url: SB_URL_NOTE + '/rest/v1/conversation_context?chatwoot_conv_id=eq.' + cwId + '&select=active_brand,active_model,active_vehicle_id&limit=1',
            headers: H_NOTE
          });
          if (Array.isArray(ctxRows) && ctxRows[0]) activeVehicleAttrs = ctxRows[0];
        }

        const memConvId = (() => { try { return $('[MEM-1] Load Lead Memory').first().json?.conversation_id; } catch(e) { return null; } })();
        const convId = $json.conv_id || $json.conversation_id || memConvId || null;
        let convRows = [];
        if (convId) {
          convRows = await __salesProdHttpRequest.call(this, {
            method: 'GET',
            url: SB_URL_NOTE + '/rest/v1/conversaciones?id=eq.' + encodeURIComponent(convId) + '&select=marca,lead_id&limit=1',
            headers: H_NOTE
          });
        } else if (cwId) {
          convRows = await __salesProdHttpRequest.call(this, {
            method: 'GET',
            url: SB_URL_NOTE + '/rest/v1/conversaciones?chatwoot_conv_id=eq.' + cwId + '&select=marca,lead_id&limit=1',
            headers: H_NOTE
          });
