const H_SB = { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' };

// F2 (2026-07-15): terminal authority gate for loss/contact-later reporting.
function lossAuthorizedByTerminalDecision(src) {
  const decision = String(src.terminal_decision || src.final_state || src.next_state || '').toUpperCase();
  const hasReason = Boolean(src.loss_reason_code || src.razon_rechazo || src.loss_reason_observation);
  const classified = String(src.loss_reason_status || '').toLowerCase() === 'classified';
  return (decision === 'LOST' || decision === 'CONTACTAR') && (src.terminal_decision_authorized === true || classified || hasReason);
}
if (!lossAuthorizedByTerminalDecision(item)) {
  return [{ json: { ...item, status: 'terminal_loss_blocked', terminal_decision_required: 'LOST_OR_CONTACTAR', trigger_perdida: false, trigger_loss: false } }];
}

const CATALOG = {
  PRICE: { final_state: 'LOST', tag: 'reason_price', comentario: 'Cliente considera que el precio es elevado', observacion: 'Cliente rechaza por precio' },
  NO_BUDGET: { final_state: 'LOST', tag: 'reason_budget', comentario: 'Cliente no cuenta con presupuesto actualmente', observacion: 'Cliente sin presupuesto' },
  HAS_OTHER_GPS: { final_state: 'LOST', tag: 'reason_other_gps', comentario: 'Cliente ya cuenta con otro servicio de rastreo', observacion: 'Cliente posee otro rastreo' },
  COMPETITOR: { final_state: 'LOST', tag: 'reason_competitor', comentario: 'Cliente está evaluando opciones con la competencia', observacion: 'Seguimiento con competencia' },
  NOT_INTERESTED: { final_state: 'LOST', tag: 'reason_not_interested', comentario: 'Cliente manifestó que no desea el servicio', observacion: 'Cliente no desea' },
  CONTACT_LATER: { final_state: 'CONTACTAR', tag: 'contact_later', comentario: 'Cliente solicita ser contactado en inicio del otro mes', observacion: 'Cliente solicita contacto posterior' }
};
function codeFromText(value) {
  const t = String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (/precio|caro|elevado|costoso/.test(t)) return 'PRICE';
  if (/presupuesto/.test(t)) return 'NO_BUDGET';
  if (/gps|rastreo|otro servicio|otro rastreador|ya cuenta|posee otro/.test(t)) return 'HAS_OTHER_GPS';
  if (/competencia|competidor|opciones|evaluando/.test(t)) return 'COMPETITOR';
  if (/contact|llamar|retomar|posterior|luego|despues|después|otro mes|proximo|próximo|mas adelante|más adelante|inicio/.test(t)) return 'CONTACT_LATER';
  if (/no quiere|no desea|no interes|no interés|no es de mi interes|no es de mi interés/.test(t)) return 'NOT_INTERESTED';
  return null;
}

let reasonCode = String(item.loss_reason_code || item.razon_rechazo || '').toUpperCase();
const nextStateUpper = String(item.next_state || '').toUpperCase();
const requestedFinalStateUpper = String(item.final_state || '').toUpperCase();
if (!CATALOG[reasonCode] && (nextStateUpper === 'CONTACTAR' || requestedFinalStateUpper === 'CONTACTAR')) reasonCode = 'CONTACT_LATER';
if (!CATALOG[reasonCode]) reasonCode = codeFromText(item.loss_reason_observation || item.observacion_api || item.razon_rechazo) || '';
const reason = CATALOG[reasonCode] || null;
const finalState = reason?.final_state || item.final_state || (nextStateUpper === 'CONTACTAR' ? 'CONTACTAR' : 'LOST');
const fsmFinalState = finalState === 'CONTACTAR' ? 'LOST' : finalState;

if (String(item.next_state || '').toUpperCase() === 'LOSS_REASON_PENDING' || String(item.loss_reason_status || '') === 'pending_prompt_sent') {
