    })
  });
  const stateResult = Array.isArray(stateRows) ? stateRows[0] : stateRows;
  const stateOk = stateResult?.changed === true || stateResult?.reason === 'no_change';
  if (!stateOk) {
    return [{ json: { ...item, status: 'state_blocked_not_reported', conv_id: convId || null, final_state: finalState, fsm_final_state: fsmFinalState, loss_reason_code: reasonCode, state_transition: stateResult } }];
  }
  await __salesProdHttpRequest.call(this, {
    method: 'PATCH',
    url: SB_URL + '/rest/v1/conversaciones?id=eq.' + encodeURIComponent(convId),
