      loss_reason_comment: reason.comentario,
      loss_reason_observation: reason.observacion,
      loss_reason_date: now,
      final_state: finalState,
      ultima_respuesta_at: now
    })
  });
  await __salesProdHttpRequest.call(this, {
    method: 'PATCH',
    url: SB_URL + '/rest/v1/lead_memory?conversation_id=eq.' + encodeURIComponent(convId),
    headers: { ...H_SB, Prefer: 'return=minimal' },
    body: JSON.stringify({
