      loss_reason_code: reasonCode,
      loss_reason_comment: reason.comentario,
      last_customer_decision: reasonCode,
      conversation_closed_reason: reason.observacion,
      outbound_sequence_status: 'COMPLETED',
      customer_engaged: true,
      followup_at: null,
      updated_at: now
    })
  }).catch(() => null);
}

return [{ json: { ...item, status: 'final_state_queued', conv_id: convId || null, conversation_id: convId || null, final_state: finalState, fsm_final_state: fsmFinalState, loss_reason_code: reasonCode, loss_reason_comment: reason.comentario, loss_reason_observation: reason.observacion, observacion: reason.observacion, razon: reasonCode, phone, state_transition: stateResult } }];

const item = $input.first().json;
let phone = (item.telefono || '').replace(/[\s\-\(\)]/g, '');
function toE164(raw) {
  let p = raw.replace(/\+/g, '');
  if (p.startsWith('593') || p.startsWith('57') || p.startsWith('55')) return '+' + p;
  if (p.startsWith('0') && p.length === 10) return '+593' + p.slice(1);
  if (p.length === 9 && p.startsWith('9')) return '+593' + p;
  return '+' + p;
}
phone = toE164(phone);
const phoneLocal = phone.replace(/^\+/, '');
