const calData = $json.calificacion_data || {};
const campoActualizado = calData.campo_actualizado || null;
const valor = calData.valor !== undefined ? calData.valor : null;

// [QUAL-GUARD] Persist only approved free-text qualification fields.
const allowedQualificationFields = new Set(['experiencia_gps', 'problema_principal', 'tomador_decision', 'urgencia']);
let buttonCtx = {};
try { buttonCtx = $('[BTN-GUARD] Claim Button Interaction').first().json || {}; } catch (e) {}
const rawInbound = String($json.concat_message || buttonCtx.button_guard_normalized_content || '');
const interactiveTurn = buttonCtx.button_guard_is_button === true
  || Boolean(buttonCtx.button_guard_payload || buttonCtx.button_guard_key)
  || /^(?:button_action|button_payload|list_reply_id|selected_establishment_id)\s*:/im.test(rawInbound);
if (interactiveTurn || !allowedQualificationFields.has(String(campoActualizado || ''))) {
  return [{ json: { ...$json, cse_status: 'skip_save', reason: interactiveTurn ? 'interactive_not_qualification' : 'invalid_qualification_field' } }];
}
const now = new Date().toISOString();

if (!convId || !campoActualizado || valor === null) {
  return [{ json: { ...$json, cse_status: 'skip_save', reason: 'missing_cal_data', campoActualizado, valor } }];
}

const SB_URL = ($env.RENOV_SUPABASE_REST_URL || 'http://127.0.0.1:9');
