      p_source: 'cse_save_answer',
      p_metadata: { campo_actualizado: campoActualizado, marca }
    })
  });
  stateResult = Array.isArray(stateRows) ? stateRows[0] : stateRows;
} catch (e) {
  stateResult = { changed: false, reason: 'rpc_error', error: String(e.message || e).slice(0, 200) };
}
if (stateResult?.changed === true || stateResult?.reason === 'no_change') {
  await __salesProdHttpRequest.call(this, {
    method: 'PATCH',
    url: `${SB_URL}/rest/v1/conversaciones?id=eq.${convId}`,
