    tipo_evento: 'RESPUESTA_CALIFICACION',
    datos_evento: { campo: campoActualizado, valor: String(valor), pregunta_orden: pregOrden, marca }
  })
});

return [{ json: { ...$json, cse_status: 'answer_saved', preguntas_respondidas: pregRespondidas, ultima_pregunta_orden: pregOrden, state_transition: stateResult } }];

