const faqErrors = [];

function compactFaqError(source, error) {
  return {
    source,
    code: String(error?.code || error?.name || 'request_failed').slice(0, 80),
    status: Number(error?.response?.statusCode || error?.statusCode || error?.httpCode || 0) || null
  };
}

async function fetchFaq(source, url) {
  try {
    const rows = await __salesProdHttpRequest.call(this, { method: 'GET', url, headers: H });
    return Array.isArray(rows) ? rows : [];
  } catch (error) {
    faqErrors.push(compactFaqError(source, error));
    return [];
  }
}

if (!marca) {
  return [{ json: {
    ...$json,
    faq_items: [],
    necesidad_cargada: necesidad,
    faq_count: 0,
    faq_load_status: 'skipped_no_brand',
    faq_errors: [{ source: 'brand', code: 'missing_brand', status: null }]
  } }];
}

const marcaFilter = encodeURIComponent(marca);
const necesidadFilter = necesidad ? encodeURIComponent(necesidad) : null;
const [needItems, brandGeneric, genericFaq] = await Promise.all([
  necesidadFilter
    ? fetchFaq.call(this, 'need', SB_URL + '/rest/v1/catalogo_faq?select=titulo,contenido,necesidad,marca,categoria&activo=eq.true&marca=eq.' + marcaFilter + '&categoria=eq.SERVICIO_CANONICO&necesidad=eq.' + necesidadFilter + '&order=orden.asc&limit=3')
    : Promise.resolve([]),
  fetchFaq.call(this, 'brand_generic', SB_URL + '/rest/v1/catalogo_faq?select=titulo,contenido,necesidad,marca,categoria&activo=eq.true&marca=eq.' + marcaFilter + '&categoria=eq.SERVICIO_CANONICO&necesidad=is.null&order=orden.asc&limit=3'),
  fetchFaq.call(this, 'generic', SB_URL + '/rest/v1/catalogo_faq?select=titulo,contenido,necesidad,marca,categoria&activo=eq.true&marca=eq.' + marcaFilter + '&categoria=eq.SERVICIO_CANONICO&order=orden.asc&limit=2')
]);

const seen = new Set();
const merged = [...needItems, ...brandGeneric, ...genericFaq].filter(item => {
  if (!item || !item.titulo || seen.has(item.titulo)) return false;
  seen.add(item.titulo);
  return true;
}).slice(0, 5);
const faqLoadStatus = faqErrors.length === 0 ? 'ok' : merged.length > 0 ? 'partial' : 'unavailable';

return [{ json: {
  ...$json,
  faq_items: merged,
