const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

async function sendBlock(text) {
  const promises = [];
  if (urlBase && token && accountId && chatwootConvId) {
    promises.push(
      httpReq({
        method: 'POST',
        url: `http://${urlBase}/api/v1/accounts/${accountId}/conversations/${chatwootConvId}/messages`,
        headers: { 'api_access_token': token, 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: text, message_type: 'outgoing', private: false })
      }).catch(() => {})
    );
  }
  if (clientPhone) {
    promises.push(
      httpReq({
        method: 'POST',
        url: `https://graph.facebook.com/v23.0/${META_PHONE_ID}/messages`,
        headers: { 'Authorization': 'Bearer ' + META_TOKEN, 'Content-Type': 'application/json' },
        body: JSON.stringify({ messaging_product: 'whatsapp', to: clientPhone, type: 'text', text: { body: text } })
      }).catch(() => {})
    );
  }
  await Promise.all(promises);
}

let blocksSent = 0;

if (faqItems.length > 0) {
  const needLabels = {
    SEGURIDAD: 'seguridad y protección de su vehículo',
    MONITOREO: 'monitoreo remoto',
    FLOTA: 'gestión de flota',
    RECUPERACION_ROBO: 'protección ante robo'
  };
  const needLabel = needLabels[necesidad] || 'sus necesidades';

  // Bloque 1: Intro
  const intro = `Basándonos en nuestra conversación, le comparto los beneficios de *${serviceName}* para ${needLabel} 👇`;
  await sendBlock(intro);
  blocksSent++;
  await delay(1500);

  // Bloque 2: SOLO el primer item
  const firstItem = faqItems[0];
  await sendBlock(`*${firstItem.titulo}*\n${firstItem.contenido}`);
  blocksSent++;

  // Guardar el resto en faq_queue
  const remainingItems = faqItems.slice(1);

  // Buscar o crear registro en datos_calificacion
  const existing = await httpReq({
    method: 'GET',
    url: `${SB_URL}/rest/v1/datos_calificacion?conversacion_id=eq.${convId}&select=id`,
    headers: { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY }
  });

  if (existing && existing.length > 0) {
    await httpReq({
      method: 'PATCH',
      url: `${SB_URL}/rest/v1/datos_calificacion?conversacion_id=eq.${convId}`,
