  }
}

// Transicionar estado a PRESENTACION_SOLUCION por FSM
const stateRows = await httpReq({
  method: 'POST',
  url: `${SB_URL}/rest/v1/rpc/set_conversation_state`,
  headers: { ...H_SB, 'Prefer': 'return=representation' },
  body: JSON.stringify({
    p_conversation_id: convId,
    p_new_state: 'VALUE_PRESENTED',
