    p_metadata: { necesidad, faq_count: faqItems.length, marca }
  })
});
const stateResult = Array.isArray(stateRows) ? stateRows[0] : stateRows;
const stateOk = stateResult?.changed === true || stateResult?.reason === 'no_change';
if (!stateOk) {
  return [{ json: { ...$json, cse_status: 'state_blocked', estado: stateResult?.old_state || $json.estado, necesidad_principal: necesidad, state_transition: stateResult, wa_message: '', wa_to: clientPhone } }];
}
await httpReq({
  method: 'PATCH',
  url: `${SB_URL}/rest/v1/conversaciones?id=eq.${convId}`,
  headers: { ...H_SB, 'Prefer': 'return=minimal' },
  body: JSON.stringify({ ultima_respuesta_at: now })
});

// Registrar evento
await httpReq({
  method: 'POST',
  url: `${SB_URL}/rest/v1/eventos_conversacion`,
  headers: { ...H_SB, 'Prefer': 'return=minimal' },
  body: JSON.stringify({
    conversation_id: convId,
    tipo_evento: 'ESTADO_CAMBIADO',
    datos_evento: {
      estado_nuevo: 'VALUE_PRESENTED',
      necesidad,
      faq_count: faqItems.length,
      faq_queue_remaining: Math.max(0, faqItems.length - 1),
      blocks_sent: blocksSent,
