    }
  })
});

return [{ json: { ...$json, cse_status: 'solution_started', estado: 'VALUE_PRESENTED', state_transition: stateResult, faq_count: faqItems.length, blocks_sent: blocksSent, wa_message: '', wa_to: clientPhone } }];

