const MARCA_IDS = { KIA: 'e0604c9c-d124-43cf-99cf-2f84f37139d7', HYUNDAI: '54dda244-260c-440d-93ea-33a8aea7f49a' };
const PLAN_CODES = { KIA: 'TELEMETRIA', HYUNDAI: 'MY_HYUNDAI' };

