let modelo = String($json.modelo || $json.contact_context?.additional_attributes?.modelo || $json.contact_context?.additional_attributes?.model || '').trim();

function parsePositiveInt(value) {
  const n = parseInt(value, 10);
  return Number.isFinite(n) && n > 0 ? n : 0;
}
function safeEditFields() {
  try { return $('Edit Fields').first().json || {}; } catch (e) { return {}; }
}
function normalizePhone(raw) {
  let p = String(raw || '').replace(/[\s\-()]/g, '').trim();
  if (!p) return '';
  if (p.startsWith('+')) return p;
  if (p.startsWith('00')) return '+' + p.slice(2);
  if (p.startsWith('0') && p.length === 10) return '+593' + p.slice(1);
  if (p.length === 9 && p.startsWith('9')) return '+593' + p;
  if (/^593\d{9}$/.test(p)) return '+' + p;
  return p.startsWith('+') ? p : '+' + p;
}
const efForPricing = safeEditFields();
function resolveChatwootConvId() {
  const candidates = [
    $json.chatwoot_conv_id,
    $json.conversation_display_id,
    $json.conversation?.id,
    $json.conversation?.display_id,
    $json.body?.conversation?.id,
    $json.body?.conversation?.display_id,
    efForPricing.conversation_display_id,
    efForPricing.sessionId,
    efForPricing.body?.conversation?.id,
    efForPricing.body?.conversation?.display_id,
  ];
  for (const value of candidates) {
    const n = parsePositiveInt(value);
    if (n) return n;
  }
  return 0;
}
function resolvePhone() {
  return normalizePhone(
    $json.contact_context?.phone_number
    || $json.phone
    || $json.telefono_1
    || $json.telefono
    || $json.body?.conversation?.meta?.sender?.phone_number
    || $json.body?.sender?.phone_number
    || efForPricing.body?.conversation?.meta?.sender?.phone_number
    || efForPricing.body?.sender?.phone_number
    || ''
  );
}

