}

async function hydrateConversationByUrl(url) {
  try {
    const lookup = await __salesProdHttpRequest.call(this, { method: 'GET', url, headers: H });
    const row = Array.isArray(lookup) ? lookup[0] : lookup;
    if (row) {
      if (!convId) convId = row.id;
      const dbMarca = String(row.marca || '').toUpperCase();
      if (dbMarca === 'KIA' || dbMarca === 'HYUNDAI') marca = dbMarca;
      const dbModelo = String(row.modelo || '').trim();
      if (dbModelo) modelo = dbModelo;
      return true;
    }
  } catch (e) { /* non-fatal */ }
  return false;
}

if (chatwootConvId > 0) {
