function formatPrice(value) {
  const n = Number.parseFloat(value);
  return Number.isFinite(n) ? n.toFixed(2) : '0.00';
}

function durationLabel(months) {
  const m = Number(months) || 0;
  if (m > 0 && m % 12 === 0) {
    const years = m / 12;
    return years === 1 ? '1 año' : years + ' años';
  }
  return m + ' meses';
}

function truncate(text, max) {
  const value = String(text || '').trim();
  return value.length <= max ? value : value.slice(0, Math.max(0, max - 1)).trim() + '…';
}

function normalizeId(text) {
  return String(text || 'plan')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '') || 'plan';
}

function planId(plan) {
  return 'plan_' + normalizeId(plan.codigo_plan || plan.nombre_plan || 'servicio') + '_' + Number(plan.meses || 0) + 'm';
}

function planTitle(plan) {
  return durationLabel(plan.meses) + ' $' + formatPrice(plan.precio_usd);
}

function priceLines() {
  return planes.map(p => '• ' + durationLabel(p.meses) + ': $' + formatPrice(p.precio_usd));
}

function groupPlans() {
  const groups = {};
  for (const plan of planes) {
    const type = plan.nombre_plan || plan.codigo_plan || 'PLAN';
    if (!groups[type]) groups[type] = [];
    groups[type].push(plan);
  }
  return groups;
}

function serviceLine() {
  const names = [...new Set(planes.map(p => p.nombre_plan || p.codigo_plan).filter(Boolean))];
  return names.length ? names.join(' / ') : serviceName;
}

function buildFallbackMessage() {
  const groups = groupPlans();
  const lines = [
    'Aquí están las opciones disponibles para *' + vehicleLabel() + '* (IVA incluido):',
    ''
  ];

  for (const [type, planList] of Object.entries(groups)) {
    lines.push('*' + type + '*');
    for (const p of planList) {
      lines.push('• ' + durationLabel(p.meses) + ': $' + formatPrice(p.precio_usd));
    }
    lines.push('');
  }

  lines.push('_Incluye: instalación profesional, monitoreo 24/7, app móvil y soporte técnico._');
  lines.push('');
  lines.push('Elija una opción para continuar.');
  return lines.join('\n');
}

