function isDefinitiveProviderRejection(error) {
  const status = Number(error?.statusCode || error?.response?.statusCode || error?.response?.status || 0);
  return status >= 400 && status < 500 && status !== 408 && status !== 429;
}

function formatHttpError(e) {
  const base = e?.message || String(e);
  const data = e?.response?.data || e?.error || e?.cause?.response?.data;
  if (!data) return base;
  try { return base + ' | ' + JSON.stringify(data).slice(0, 500); }
  catch (_) { return base + ' | ' + String(data).slice(0, 500); }
}

async function sendMeta(payload) {
  let lastError = null;
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      return await __salesProdHttpRequest.call(this, {
        method: 'POST',
        url: 'https://graph.facebook.com/v23.0/' + META_PHONE_ID + '/messages',
        headers: { 'Authorization': 'Bearer ' + META_TOKEN, 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
    } catch (e) {
      lastError = e;
      // H8: solo reintentar errores de conexión claros (el request no salió).
      // Timeouts/HTTP errors NO se reintentan: Meta pudo haber recibido el
      // mensaje y el segundo intento lo duplicaría al cliente.
      const _connCode = String((e && (e.code || (e.cause && e.cause.code))) || '');
      if (!['ECONNREFUSED', 'ENOTFOUND', 'EAI_AGAIN'].includes(_connCode)) break;
      if (attempt < 2) await new Promise(resolve => setTimeout(resolve, 900));
    }
  }
  throw lastError;
}

