        caption: 'Propuesta Comercial ' + serviceName
      }
    });
    metaAccepted = true;
    const metaMessageId = pdfResponse?.messages?.[0]?.id || null;
    await __salesProdHttpRequest.call(this, {
      method: 'POST',
      url: SB_URL + '/rest/v1/rpc/complete_pricing_document_delivery',
      headers: H_SB,
      body: JSON.stringify({ p_conversation_id: convId, p_document_key: pdfDocumentKey, p_claim_token: pdfDeliveryClaimToken, p_status: 'SENT', p_wa_message_id: metaMessageId, p_error_message: null })
    }).catch(e => { console.log('PDF completion persistence failed after Meta acceptance:', e.message); return null; });
    await registerPricingPdfSent.call(this, metaMessageId).catch(e => { console.log('PDF audit event failed:', e.message); return null; });
    return true;
  } catch(e) {
    pdfError = formatHttpError(e);
    if (!metaAccepted) {
      await __salesProdHttpRequest.call(this, {
        method: 'POST',
        url: SB_URL + '/rest/v1/rpc/complete_pricing_document_delivery',
        headers: H_SB,
        body: JSON.stringify({ p_conversation_id: convId, p_document_key: pdfDocumentKey, p_claim_token: pdfDeliveryClaimToken, p_status: isDefinitiveProviderRejection(e) ? 'FAILED' : 'UNKNOWN', p_wa_message_id: null, p_error_message: pdfError })
      }).catch(() => null);
    }
    return metaAccepted;
  }
}

