let inboundMessageId = '';
try {
  const _efBody = $('Edit Fields').first().json.body || {};
  inboundMessageId = String(_efBody.message_id || _efBody.id || _efBody.conversation?.messages?.[0]?.id || '').slice(0, 120);
} catch(e) {}

async function hasRecentPricingSent() {
  if (!convId || !inboundMessageId) return false;
  try {
    const rows = await __salesProdHttpRequest.call(this, {
      method: 'GET',
      url: SB_URL + '/rest/v1/eventos_conversacion?conversation_id=eq.' + encodeURIComponent(convId) + '&tipo_evento=eq.PRICING_SENT&datos_evento->>inbound_message_id=eq.' + encodeURIComponent(inboundMessageId) + '&select=id&limit=1',
      headers: H_SB
    });
    return Array.isArray(rows) && rows.length > 0;
  } catch(e) {
    return false;
  }
}

async function registerPricingSkipped(reason) {
  if (!convId) return;
  try {
    await __salesProdHttpRequest.call(this, {
      method: 'POST',
      url: SB_URL + '/rest/v1/eventos_conversacion',
      headers: { ...H_SB, 'Prefer': 'return=minimal' },
      body: JSON.stringify({
        conversation_id: convId,
        tipo_evento: 'PRICING_SKIPPED',
        actor: 'CRIS',
        datos_evento: { source: 'cse_send_pricing', reason: String(reason || 'unknown').slice(0, 160), inbound_message_id: inboundMessageId, marca }
      })
    });
  } catch(e) {}
}

async function registerPricingPdfSent(metaMessageId) {
  if (!convId) return;
  await __salesProdHttpRequest.call(this, {
    method: 'POST',
    url: SB_URL + '/rest/v1/eventos_conversacion',
    headers: { ...H_SB, 'Prefer': 'return=minimal' },
    body: JSON.stringify({
      conversation_id: convId,
      tipo_evento: 'PRICING_PDF_SENT',
      actor: 'CRIS',
      datos_evento: { source: 'cse_send_pricing', marca, pdf_sent: true, meta_message_id: metaMessageId }
    })
  });
}

async function registerPricingSent(details = {}) {
  if (!convId) return;
  try {
    await __salesProdHttpRequest.call(this, {
      method: 'POST',
      url: SB_URL + '/rest/v1/eventos_conversacion',
      headers: { ...H_SB, 'Prefer': 'return=minimal' },
      body: JSON.stringify({
        conversation_id: convId,
        tipo_evento: 'PRICING_SENT',
        actor: 'CRIS',
        datos_evento: {
          source: 'cse_send_pricing',
          marca,
          chatwoot_conv_id: chatwootConvId,
          client_phone: clientPhone,
          inbound_message_id: inboundMessageId,
          ...details
        }
      })
    });
  } catch(e) {}
}

const isReviewOtherPlan = String($json.last_response_type || $json.output?.last_response_type || $json.deterministic_status || '').toUpperCase().includes('REVIEW_OTHER_PLAN');
const pricingState = assistedHandoffPricing
  ? 'HANDOFF_HUMAN'
  : (isReviewOtherPlan
    ? 'QUOTED'
    : ($json.selected_plan || $json.next_state === 'PLAN_SELECTED' ? 'PLAN_SELECTED' : 'QUOTED'));

if (planes.length === 0) {
  if (assistedHandoffPricing) {
    const noPlansReason = String($json.pricing_error || $json.pricing_error_code || 'no_eligible_plans')
      .replace(/[^a-z0-9:_-]/gi, '_').slice(0, 160);
    await registerPricingSkipped.call(this, noPlansReason);
    await sendChatwootMessage.call(this, 'ALERTA INTERNA: cotización asistida no disponible\nMotivo: ' + noPlansReason + '\nConversation ID: ' + (convId || ''), true);
    return [{ json: {
      ...$json,
      output: {
        ...(typeof $json.output === 'object' && $json.output ? $json.output : {}),
        reply: { text: '', channel_hints: { attachments: [] } },
        show_price: false,
        skip_pdf: true,
        next_state: 'HANDOFF_HUMAN',
        price_suppressed_reason: 'PRICE_BLOCKED_BY_HANDOFF'
      },
      cse_status: 'assisted_no_plans_suppressed',
      estado: 'HANDOFF_HUMAN',
      next_state: 'HANDOFF_HUMAN',
      is_show_price: false,
      pricing_error: noPlansReason,
      skip_generic_whatsapp_send: true,
      wa_message: '',
      pricing_fallback_text: '',
      send_pdf: false,
      wa_to: clientPhone
    } }];
  }
  let previousMemory = {};
  try { previousMemory = $('[MEM-1] Load Lead Memory').first().json || {}; } catch (e) {}
  const safeState = String(previousMemory.conversation_state || $json.mem_state || $json.conversation_state || 'VALUE_PRESENTED').toUpperCase();
  const safeLastResponseType = previousMemory.last_response_type || null;
  const noPlansReason = String($json.pricing_error || $json.pricing_error_code || 'no_eligible_plans')
    .replace(/[^a-z0-9:_-]/gi, '_').slice(0, 160);
  const publicFallback = [
    'En este momento no pude cargar las opciones vigentes para ' + vehicleLabel() + '.',
    'Para no compartirle valores incorrectos, prefiero verificarlos.',
    '¿Desea que un asesor le comparta la cotización actualizada?'
  ].join('\n');

  await registerPricingSkipped.call(this, noPlansReason);
  let publicFallbackSent = await sendFallbackText.call(this, publicFallback);
  let publicFallbackMode = publicFallbackSent ? 'meta_text' : 'none';
  if (!publicFallbackSent) {
    publicFallbackSent = Boolean(await sendChatwootMessage.call(this, publicFallback, false));
    if (publicFallbackSent) publicFallbackMode = 'chatwoot_public';
  }
  const internalNote = [
    'ALERTA INTERNA: cotización no disponible',
    'Motivo: ' + noPlansReason,
    'Conversation ID: ' + (convId || ''),
    'Chatwoot Conv ID: ' + (chatwootConvId || ''),
    'Marca: ' + (marca || 'sin identificar'),
    'Planes elegibles: 0',
    'Estado conservado: ' + safeState,
    'Fallback público: ' + (publicFallbackSent ? publicFallbackMode : 'falló')
  ].join('\n');
  const internalNoteSent = Boolean(await sendChatwootMessage.call(this, internalNote, true));

  return [{ json: {
    ...$json,
    output: {
      ...(typeof $json.output === 'object' && $json.output ? $json.output : {}),
      show_price: false,
      skip_pdf: true,
      next_state: safeState,
      last_response_type: safeLastResponseType,
      price_suppressed_reason: assistedHandoffPricing ? 'PRICE_BLOCKED_BY_HANDOFF' : 'PRICING_UNAVAILABLE_NO_PLANS'
    },
    cse_status: 'pricing_unavailable_no_plans',
    estado: safeState,
    next_state: safeState,
    is_show_price: false,
    last_response_type: safeLastResponseType,
    state_transition: null,
    planes_count: 0,
    pricing_delivery_mode: publicFallbackSent ? publicFallbackMode : 'none',
    pricing_error: noPlansReason,
    send_pdf: false,
    pdf_error: null,
    wa_message: publicFallbackSent ? '' : publicFallback,
    pricing_fallback_text: publicFallback,
    skip_generic_whatsapp_send: publicFallbackSent,
    public_fallback_sent: publicFallbackSent,
    internal_note_sent: internalNoteSent,
    wa_to: clientPhone
  } }];
}

if (await hasRecentPricingSent.call(this)) {
  await registerPricingSkipped.call(this, 'duplicate_same_inbound_message');
  return [{
    json: {
      ...$json,
      cse_status: 'skip_duplicate_pricing',
      estado: $json.estado || pricingState,
      planes_count: planes.length,
      pricing_delivery_mode: 'duplicate_guard',
      send_pdf: SEND_PDF,
      skip_generic_whatsapp_send: true,
      wa_message: '',
      wa_to: clientPhone
    }
  }];
}

let stateResult = null;
let stateOk = false;
try {
  const stateRows = await __salesProdHttpRequest.call(this, {
    method: 'POST',
    url: SB_URL + '/rest/v1/rpc/set_conversation_state',
    headers: { ...H_SB, 'Prefer': 'return=representation' },
    body: JSON.stringify({
      p_conversation_id: convId,
      p_new_state: pricingState,
      p_source: 'cse_send_pricing',
      p_metadata: { marca, planes_count: planes.length, pricing_delivery_mode: 'pre_send_lock' }
    })
  });
  stateResult = Array.isArray(stateRows) ? stateRows[0] : stateRows;
  stateOk = stateResult?.changed === true || ['no_change','unchanged'].includes(stateResult?.reason);
} catch(e) {
  stateResult = { changed: false, reason: 'rpc_error', error: String(e.message || e).slice(0, 200) };
}

if (!stateOk) {
  await registerPricingSkipped.call(this, 'state_blocked:' + String(stateResult?.reason || 'unknown'));
  return [{
    json: {
      ...$json,
      cse_status: ['no_change','unchanged'].includes(stateResult?.reason) ? 'skip_duplicate_pricing' : 'state_blocked',
      estado: stateResult?.old_state || $json.estado,
      planes_count: planes.length,
      pricing_delivery_mode: 'blocked_before_send',
      pricing_error: pricingError,
      send_pdf: SEND_PDF,
      pdf_error: pdfError,
      skip_generic_whatsapp_send: true,
      wa_message: '',
      wa_to: clientPhone,
      state_transition: stateResult,
      output: {
        ...(typeof $json.output === 'object' && $json.output ? $json.output : {}),
        show_price: false,
        skip_pdf: true,
        next_state: assistedHandoffPricing ? 'HANDOFF_HUMAN' : (stateResult?.old_state || $json.estado),
        price_suppressed_reason: assistedHandoffPricing ? 'PRICE_BLOCKED_BY_HANDOFF' : 'STATE_TRANSITION_BLOCKED'
      }
    }
  }];
}

if (planes.length > 0) {
  const fallbackMessage = buildFallbackMessage();
  const planInteractionPayload = {
    plans: planes.map(p => ({ id: planId(p), name: p.nombre_plan || p.codigo_plan || 'PLAN', duration_months: Number(p.meses || 0), price_usd: Number(formatPrice(p.precio_usd)) }))
  };
  try {
    const preparedRows = await preparePlanInteraction.call(this, convId, planes.map(p => planId(p).toUpperCase()), planInteractionPayload);
    const preparedRow = Array.isArray(preparedRows) ? preparedRows[0] : preparedRows;
    interactionPrepared = preparedRow?.should_send === true;
    activeInteractionId = preparedRow?.interaction_id_out || null;
    interactionDeliveryToken = preparedRow?.delivery_token_out || null;
    if (!interactionPrepared) throw new Error(preparedRow?.reason || 'plan_interaction_not_prepared');
  } catch (e) {
    pricingError = [pricingError, 'prepare_interaction:' + formatHttpError(e)].filter(Boolean).join(' | ');
  }

  if (interactionPrepared) {
    try {
      if (!await authorizePlanDelivery.call(this)) throw new Error('plan_delivery_not_authorized');
    } catch (e) {
      pricingError = [pricingError, 'authorize_interaction:' + formatHttpError(e)].filter(Boolean).join(' | ');
      await cancelPlanInteraction.call(this, pricingError).catch(() => null);
      interactionPrepared = false;
    }
  }

  // Reserve the menu before any public output, then keep the interactive CTA last.
  let pdfSent = false;
  if (interactionPrepared) {
    await claimPdfDelivery.call(this);
    pdfSent = await sendPdf.call(this);
  }
  const payload = interactionPrepared ? buildInteractivePayload() : null;
  let interactiveSent = false;
  let fallbackSent = false;
  let chatwootFallbackSent = false;

  if (payload && interactionPrepared) {
    try {
      if (!await authorizePlanDelivery.call(this)) throw new Error('plan_delivery_not_authorized_before_menu');
    } catch (e) {
      pricingError = [pricingError, 'authorize_menu:' + formatHttpError(e)].filter(Boolean).join(' | ');
      await cancelPlanInteraction.call(this, pricingError).catch(() => null);
      interactionPrepared = false;
    }
  }
  if (payload && interactionPrepared) {
    try {
      const metaResp = await sendMeta.call(this, payload);
      interactiveMessageId = metaResp?.messages?.[0]?.id || null;
      interactiveSent = Boolean(interactiveMessageId);
      pricingDeliveryMode = 'interactive_button';
      if (!interactiveSent) {
        interactiveDeliveryUnknown = true;
        await markPlanDeliveryUnknown.call(this, 'meta_accepted_without_message_id').catch(() => null);
      }
    } catch(e) {
      pricingError = formatHttpError(e);
      interactiveDeliveryUnknown = !isDefinitiveProviderRejection(e);
      if (interactiveDeliveryUnknown) {
        await markPlanDeliveryUnknown.call(this, pricingError).catch(() => null);
      }
    }
  }

  if (interactiveSent) {
    try {
      const activeRows = await activatePlanInteraction.call(
        this,
        convId,
        activeInteractionId,
        interactionDeliveryToken,
        interactiveMessageId,
        planInteractionPayload
      );
      const activeRow = Array.isArray(activeRows) ? activeRows[0] : activeRows;
      interactionArmed = activeRow?.activated === true;
      if (!interactionArmed) throw new Error(activeRow?.reason || 'active_plan_interaction_not_created');
    } catch (e) {
      interactionArmed = false;
      pricingError = [pricingError, 'interaction:' + formatHttpError(e)].filter(Boolean).join(' | ');
      interactiveDeliveryUnknown = true;
      await markPlanDeliveryUnknown.call(this, pricingError).catch(() => null);
    }
    const note = buildStructuredPricingNote('COTIZACIÓN INTERACTIVA ENVIADA POR WHATSAPP', {
      mode: pricingDeliveryMode,
      pdfSent,
      pdfError,
      pricingError,
      fallbackMessage
    });
    await sendChatwootMessage.call(this, note, true);
  } else if (interactionPrepared && !assistedHandoffPricing && !interactiveDeliveryUnknown) {
    const fallbackAuthorized = await authorizePlanDelivery.call(this).catch(() => false);
    if (!fallbackAuthorized) pricingError = [pricingError, 'fallback_not_authorized'].filter(Boolean).join(' | ');
    pricingDeliveryMode = 'text_fallback';
    fallbackSent = fallbackAuthorized ? await sendFallbackText.call(this, fallbackMessage) : false;
    if (fallbackAuthorized && !fallbackSent) {
      chatwootFallbackSent = await sendChatwootMessage.call(this, fallbackMessage, false);
      if (chatwootFallbackSent) {
        fallbackSent = true;
        pricingDeliveryMode = 'chatwoot_fallback';
      }
    }
    const note = buildStructuredPricingNote('COTIZACIÓN FALLBACK TEXTO ENVIADA POR WHATSAPP', {
      mode: pricingDeliveryMode,
      pdfSent,
      fallbackSent,
      chatwootFallbackSent,
      pricingError,
      pdfError,
      fallbackMessage
    });
    await sendChatwootMessage.call(this, note, true);
  }

  if (interactionPrepared && !interactionArmed && !interactiveDeliveryUnknown) {
    await cancelPlanInteraction.call(this, pricingError || 'interactive_delivery_failed').catch(() => null);
  }

  if (interactionPrepared && !interactionArmed && !interactiveDeliveryUnknown) {
    await cancelPlanInteraction.call(this, pricingError || 'interactive_delivery_failed').catch(() => null);
  }

  pricingDelivered = assistedHandoffPricing
    ? interactiveSent && interactionArmed
    : fallbackSent || (interactiveSent && interactionArmed);
  postPricingHandoffReady = $json.post_pricing_discount_handoff === true && interactiveSent && interactionArmed;
  if (pricingDelivered) {
    await registerPricingSent.call(this, {
      pricing_delivery_mode: pricingDeliveryMode,
      pdf_sent: pdfSent,
      fallback_sent: fallbackSent,
      chatwoot_fallback_sent: chatwootFallbackSent,
      interactive_sent: interactiveSent,
      interaction_armed: interactionArmed,
      active_interaction_id: activeInteractionId,
      pricing_error: pricingError,
      pdf_error: pdfError,
      plans_shown: planes.map(p => ({ id: planId(p), name: p.nombre_plan || p.codigo_plan || 'PLAN', duration_months: Number(p.meses || 0), price_usd: Number(formatPrice(p.precio_usd)) }))
    });
  }

  if ((SEND_PDF && !pdfSent) || pdfError || pricingError || !pricingDelivered) {
    await alertInternalFailure.call(this, 'pricing_delivery', { pdfSent, interactiveSent, interactionArmed, activeInteractionId, fallbackSent, chatwootFallbackSent, pdfError, pricingError });
  }

  // Este nodo ya es dueño del envío público de cotización. Nunca reenviar por el sender genérico.
  wa_message_out = '';
}

try {
  await __salesProdHttpRequest.call(this, {
    method: 'PATCH',
    url: SB_URL + '/rest/v1/conversaciones?id=eq.' + convId,
    headers: { ...H_SB, 'Prefer': 'return=minimal' },
    body: JSON.stringify({ ultima_respuesta_at: now })
  });
} catch(e) { /* Supabase PATCH — non-fatal */ }

try {
  await __salesProdHttpRequest.call(this, {
    method: 'PATCH',
    url: SB_URL + '/rest/v1/lead_memory?conversation_id=eq.' + convId,
    headers: { ...H_SB, 'Prefer': 'return=minimal' },
    body: JSON.stringify({ conversation_state: pricingState, last_response_type: 'PRICING_PRESENTED', updated_at: now })
  });
} catch(e) { /* lead_memory PATCH — non-fatal */ }

try {
  await __salesProdHttpRequest.call(this, {
    method: 'POST',
    url: SB_URL + '/rest/v1/eventos_conversacion',
    headers: { ...H_SB, 'Prefer': 'return=minimal' },
    body: JSON.stringify({
      conversation_id: convId,
      tipo_evento: 'ESTADO_CAMBIADO',
      datos_evento: {
        estado_nuevo: pricingState,
        planes_count: planes.length,
        marca,
        pricing_delivery_mode: pricingDeliveryMode,
        pricing_error: pricingError,
        pdf_sent: SEND_PDF && !!(PDF_URLS[marca]) && !pdfError,
        pdf_error: pdfError,
        plans_shown: planes.map(p => ({ id: planId(p), name: p.nombre_plan || p.codigo_plan || 'PLAN', duration_months: Number(p.meses || 0), price_usd: Number(formatPrice(p.precio_usd)) })),
        price_text_sent: buildFallbackMessage()
      }
    })
  });
} catch(e) {}

return [{
  json: {
    ...$json,
    cse_status: pricingDelivered ? 'pricing_sent' : 'pricing_delivery_failed',
    price_suppressed_reason: assistedHandoffPricing && !pricingDelivered ? 'PRICE_BLOCKED_BY_HANDOFF' : null,
    estado: pricingState,
    state_transition: stateResult,
    planes_count: planes.length,
    pricing_delivery_mode: pricingDeliveryMode,
    pricing_error: pricingError,
    send_pdf: SEND_PDF,
    pdf_error: pdfError,
    wa_message: wa_message_out,
    pricing_fallback_text: planes.length > 0 ? buildFallbackMessage() : '',
    skip_generic_whatsapp_send: true,
    wa_to: clientPhone,
    post_pricing_handoff_ready: postPricingHandoffReady,
    preserve_plan_selection_interaction: postPricingHandoffReady,
    active_plan_interaction_id: activeInteractionId,
    output: {
      ...(typeof $json.output === 'object' && $json.output ? $json.output : {}),
      next_state: pricingState,
      show_price: pricingDelivered,
      skip_pdf: !SEND_PDF,
      price_suppressed_reason: assistedHandoffPricing && !pricingDelivered ? 'PRICE_BLOCKED_BY_HANDOFF' : null
    }
  }
}];

async function __salesProdHttpRequest(opts) {
  if (opts && String(opts.url || '').includes('/rest/v1/')) {
    opts = {
      ...opts,
      headers: {
        ...(opts.headers || {}),
        'Accept-Profile': 'sales_prod',
        'Content-Profile': 'sales_prod',
      },
    };
  }
  return this.helpers.httpRequest(opts);
}

// CSE Fase 6 — Discount handoff: nota privada + label + estado HANDOFF_DESCUENTO
let convId = $json.conv_id || $json.conversation_id || null;
const ef = $('Edit Fields').first().json || {};
const senderAttrs = ef.body?.conversation?.meta?.sender?.additional_attributes || {};
const chatwootConvId = parseInt(ef.conversation_display_id || ef.body?.conversation?.id || $json.chatwoot_conv_id || '', 10) || null;
let marca = String($json.marca || senderAttrs.marca || '').toUpperCase();
let nombreCliente = $json.nombre_cliente || ef.body?.sender?.name || ef.body?.conversation?.meta?.sender?.name || 'Cliente';
let modelo = $json.modelo || senderAttrs.modelo || '';
let quicklinkId = $json.quicklink_id || senderAttrs.quicklink_id || null;
const necesidad = $json.necesidad_principal || $json.ai_structured?.necesidad_detectada || null;
const now = new Date().toISOString();
const assistedAtDiscount = String($json.mem_state || $json.conversation_state || '').toUpperCase() === 'HANDOFF_HUMAN';

const SB_URL = ($env.RENOV_SUPABASE_REST_URL || 'http://127.0.0.1:9');
const SB_KEY = $env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET';
const H_SB = { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' };

let convRow = null;
if (!convId && chatwootConvId) {
  try {
    const rows = await __salesProdHttpRequest.call(this, {
      method: 'GET',
      url: `${SB_URL}/rest/v1/conversaciones?chatwoot_conv_id=eq.${chatwootConvId}&select=id,marca,nombre,telefono,modelo,quicklink_id&limit=1`,
      headers: H_SB
    });
    convRow = Array.isArray(rows) ? rows[0] : null;
    if (convRow?.id) convId = convRow.id;
  } catch (e) {}
}
if (convRow) {
  marca = marca || String(convRow.marca || '').toUpperCase();
  nombreCliente = nombreCliente === 'Cliente' ? (convRow.nombre || nombreCliente) : nombreCliente;
  modelo = modelo || convRow.modelo || '';
  quicklinkId = quicklinkId || convRow.quicklink_id || null;
}
if (convId && (!marca || !modelo || !quicklinkId || nombreCliente === 'Cliente')) {
  try {
    const rows = await __salesProdHttpRequest.call(this, {
      method: 'GET',
      url: `${SB_URL}/rest/v1/conversaciones?id=eq.${convId}&select=marca,nombre,telefono,modelo,quicklink_id&limit=1`,
      headers: H_SB
    });
    const row = Array.isArray(rows) ? rows[0] : null;
    if (row) {
      marca = marca || String(row.marca || '').toUpperCase();
      nombreCliente = nombreCliente === 'Cliente' ? (row.nombre || nombreCliente) : nombreCliente;
      modelo = modelo || row.modelo || '';
      quicklinkId = quicklinkId || row.quicklink_id || null;
    }
  } catch (e) {}
}
if (!convId) {
  return [{ json: { ...$json, cse_status: 'descuento_handoff_skipped_no_conv_id', chatwoot_conv_id: chatwootConvId } }];
}

// Cargar datos_calificacion
let calData = null;
try {
  const calResp = await __salesProdHttpRequest.call(this, {
    method: 'GET',
    url: `${SB_URL}/rest/v1/datos_calificacion?conversation_id=eq.${convId}&select=*`,
    headers: { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY }
  });
  calData = Array.isArray(calResp) && calResp.length > 0 ? calResp[0] : null;
} catch(e) {}

const needLabels = {
    SEGURIDAD: 'Seguridad vehicular',
    MONITOREO: 'Monitoreo remoto',
    FLOTA: 'Gestión de flota',
    RECUPERACION_ROBO: 'Recuperación ante robo'
  };
  const urgenciaLabels = {
    ESTA_SEMANA: 'Esta semana',
    ESTE_MES: 'Este mes',
    PROXIMOS_MESES: 'Próximos meses',
    EXPLORANDO: 'Solo explorando'
  };

const fechaStr = new Date().toLocaleDateString('es-EC', {day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit'});

let note = `⚠️ SOLICITUD DE DESCUENTO — CRIS v4\n\n`;
note += `CLIENTE: ${nombreCliente}\n`;
note += `VEHÍCULO: ${marca} ${modelo}\n\n`;

if (calData) {
  note += `🎯 CALIFICACIÓN\n━━━━━━━━━━━━━━━━━━━━━━━\n`;
  if (calData.necesidad_clasificada) note += `Necesidad: ${needLabels[calData.necesidad_clasificada] || calData.necesidad_clasificada}\n`;
  if (calData.tomador_decision)     note += `Tomador de decisión: ${calData.tomador_decision}\n`;
  if (calData.cantidad_vehiculos)   note += `Vehículos: ${calData.cantidad_vehiculos}\n`;
  if (calData.urgencia)             note += `Urgencia: ${urgenciaLabels[calData.urgencia] || calData.urgencia}\n`;
  if (calData.score_calificacion)   note += `\n📊 SCORE: ${calData.score_calificacion}/100\n`;
}

note += `\n🔔 MOTIVO: Cliente solicita descuento o condición especial\n`;
note += `⏰ ${fechaStr}`;

const urlBase = ef.URL_OMNICEM;
const token   = ef.TOKEN || $env.RENOV_CHATWOOT_API_TOKEN || '';
const accountId      = ef.account_id;

if (urlBase && token && accountId && chatwootConvId) {
  // Best-effort: a Chatwoot failure (e.g. 404 missing conversation) must NOT abort handoff persistence below (set_conversation_state + conversaciones PATCH). Matches the .catch(()=>null) idiom used elsewhere.
  await __salesProdHttpRequest.call(this, {
    method: 'POST',
    url: `http://${urlBase}/api/v1/accounts/${accountId}/conversations/${chatwootConvId}/messages`,
    headers: { 'api_access_token': token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ content: note, message_type: 'outgoing', private: true })
  }).catch((e) => { console.log('CSE Descuento Handoff note failed (non-fatal):', e && e.message); return null; });
  // WF-09 TagManager owns Chatwoot labels; discount context remains in backend/note.
}

const stateRows = await __salesProdHttpRequest.call(this, {
  method: 'POST',
  url: `${SB_URL}/rest/v1/rpc/set_conversation_state`,
  headers: { ...H_SB, 'Prefer': 'return=representation' },
  body: JSON.stringify({
    p_conversation_id: convId,
    p_new_state: 'HANDOFF_HUMAN',
    p_source: 'cse_descuento_handoff',
    p_metadata: { necesidad, marca, motivo: 'solicita_descuento' }
  })
});
const stateResult = Array.isArray(stateRows) ? stateRows[0] : stateRows;
const stateOk = stateResult?.changed === true || ['no_change', 'unchanged'].includes(stateResult?.reason);
if (!stateOk) {
  return [{ json: { ...$json, conv_id: convId, conversation_id: convId, cse_status: 'state_blocked', estado: stateResult?.old_state || $json.estado, state_transition: stateResult } }];
}
await __salesProdHttpRequest.call(this, {
  method: 'PATCH',
  url: `${SB_URL}/rest/v1/conversaciones?id=eq.${convId}`,
  headers: { ...H_SB, 'Prefer': 'return=minimal' },
  body: JSON.stringify({ ultima_respuesta_at: now })
});

await __salesProdHttpRequest.call(this, {
  method: 'POST',
  url: `${SB_URL}/rest/v1/eventos_conversacion`,
  headers: { ...H_SB, 'Prefer': 'return=minimal' },
  body: JSON.stringify({
    conversation_id: convId,
    tipo_evento: 'ESTADO_CAMBIADO',
    datos_evento: { estado_nuevo: 'HANDOFF_HUMAN', necesidad, marca, motivo: 'solicita_descuento' }
  })
});

return [{ json: { ...$json, conv_id: convId, conversation_id: convId, chatwoot_conv_id: chatwootConvId, marca, nombre_cliente: nombreCliente, modelo, quicklink_id: quicklinkId, cse_status: assistedAtDiscount ? 'assisted_discount_recorded' : 'descuento_handoff_done', terminal_decision: assistedAtDiscount ? null : 'HANDOFF_HUMAN', terminal_decision_source: assistedAtDiscount ? 'assisted_discount_request' : 'discount_request', handoff_decision_authorized: !assistedAtDiscount, handoff_assignment_required: !assistedAtDiscount, trigger_descuento_handoff: !assistedAtDiscount, estado: 'HANDOFF_HUMAN', state_transition: stateResult } }];

async function __salesProdHttpRequest(opts) {
  if (opts && String(opts.url || '').includes('/rest/v1/')) {
    opts = {
      ...opts,
      headers: {
        ...(opts.headers || {}),
        'Accept-Profile': 'sales_prod',
        'Content-Profile': 'sales_prod',
      },
    };
  }
  return this.helpers.httpRequest(opts);
}

// CSE Fase 6 — Nota privada enriquecida + label por necesidad en handoff regular
const convId = $json.conv_id || $json.conversation_id;
let marca = String($json.marca || '').toUpperCase();
let nombreCliente = $json.nombre_cliente || '';
let modelo = $json.modelo || '';
let phone = $json.telefono_1 || $json.phone || '';
let quicklinkId = $json.quicklink_id || null;
const necesidad = $json.necesidad_principal || $json.ai_structured?.necesidad_detectada || null;

const SB_URL = ($env.RENOV_SUPABASE_REST_URL || 'http://127.0.0.1:9');
const SB_KEY = $env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET';
const H_SB = { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' };

if (convId && (!marca || !nombreCliente || !modelo || !phone || !quicklinkId)) {
  try {
    const convRows = await __salesProdHttpRequest.call(this, {
      method: 'GET',
      url: `${SB_URL}/rest/v1/conversaciones?id=eq.${convId}&select=marca,nombre,telefono,modelo,quicklink_id&limit=1`,
      headers: H_SB
    });
    const conv = Array.isArray(convRows) ? convRows[0] : null;
    if (conv) {
      marca = marca || String(conv.marca || '').toUpperCase();
      nombreCliente = nombreCliente || conv.nombre || '';
      modelo = modelo || conv.modelo || '';
      phone = conv.telefono || phone;
      quicklinkId = quicklinkId || conv.quicklink_id || null;
    }
  } catch(e) {}
}
nombreCliente = nombreCliente || 'Cliente';

// Cargar datos_calificacion
let calData = null;
try {
  const calResp = await __salesProdHttpRequest.call(this, {
    method: 'GET',
    url: `${SB_URL}/rest/v1/datos_calificacion?conversation_id=eq.${convId}&select=*`,
    headers: { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY }
  });
  calData = Array.isArray(calResp) && calResp.length > 0 ? calResp[0] : null;
} catch(e) {}

const needLabels = {
    SEGURIDAD: 'Seguridad vehicular',
    MONITOREO: 'Monitoreo remoto',
    FLOTA: 'Gestión de flota',
    RECUPERACION_ROBO: 'Recuperación ante robo'
  };
  const urgenciaLabels = {
    ESTA_SEMANA: 'Esta semana',
    ESTE_MES: 'Este mes',
    PROXIMOS_MESES: 'Próximos meses',
    EXPLORANDO: 'Solo explorando'
  };
  const needCwLabels = {
    SEGURIDAD: 'necesidad-seguridad',
    MONITOREO: 'necesidad-monitoreo',
    FLOTA: 'necesidad-flota',
    RECUPERACION_ROBO: 'necesidad-recuperacion'
  };

const fechaStr = new Date().toLocaleDateString('es-EC', {day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit'});
const rawResumen = $json.output;
const resumen = typeof rawResumen === 'string' ? rawResumen : (rawResumen ? JSON.stringify(rawResumen) : '');

let note = `🤖 RESUMEN IA — CRIS v4 Consultive Engine\n\n`;
note += `CLIENTE: ${nombreCliente}\n`;
note += `VEHÍCULO: ${marca} ${modelo}\n\n`;

if (calData) {
  note += `🎯 CALIFICACIÓN COMPLETADA\n━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  if (calData.experiencia_gps)       note += `Experiencia GPS previa: ${calData.experiencia_gps}\n`;
  const nec = calData.necesidad_clasificada;
  if (nec)                           note += `Necesidad principal: ${needLabels[nec] || nec}\n`;
  if (calData.tomador_decision)      note += `Tomador de decisión: ${calData.tomador_decision}\n`;
  if (calData.cantidad_vehiculos)    note += `Cantidad de vehículos: ${calData.cantidad_vehiculos}\n`;
  if (calData.urgencia)              note += `Urgencia: ${urgenciaLabels[calData.urgencia] || calData.urgencia}\n`;
  if (calData.problema_principal)    note += `Problema declarado: ${calData.problema_principal}\n`;
  if (calData.score_calificacion)    note += `\n📊 SCORE: ${calData.score_calificacion}/100\n`;
  if (calData.plan_sugerido)         note += `💡 PLAN SUGERIDO: ${calData.plan_sugerido}\n`;
}

if (resumen) note += `\n📝 CONTEXTO: ${resumen.slice(0, 300)}\n`;
note += `\n🔔 MOTIVO DE HANDOFF: Cliente listo para contratar\n`;
note += `⏰ ${fechaStr}`;

const urlBase = $('Edit Fields').first().json.URL_OMNICEM;
const token   = $('Edit Fields').first().json.TOKEN || $env.RENOV_CHATWOOT_API_TOKEN || '';
const accountId      = $('Edit Fields').first().json.account_id;
const chatwootConvId = $('Edit Fields').first().json.conversation_display_id;

let chatwootNoteSent = false;
if (urlBase && token && accountId && chatwootConvId) {
  // Best-effort: a Chatwoot failure (e.g. 404 missing conversation) must NOT abort handoff persistence downstream (GANADO). Matches the .catch(()=>null) idiom used elsewhere.
  const _noteResp = await __salesProdHttpRequest.call(this, {
    method: 'POST',
    url: `http://${urlBase}/api/v1/accounts/${accountId}/conversations/${chatwootConvId}/messages`,
    headers: { 'api_access_token': token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ content: note, message_type: 'outgoing', private: true })
  }).catch((e) => { console.log('CSE Post-Handoff Enrich note failed (non-fatal):', e && e.message); return null; });
  chatwootNoteSent = _noteResp !== null;

  // WF-09 TagManager owns need/status labels; keep the enriched handoff note only.
}

return [{ json: { ...$json, conv_id: convId, conversation_id: convId, marca, nombre_cliente: nombreCliente, modelo, phone, telefono_1: phone, quicklink_id: quicklinkId, cse_status: 'handoff_enriched', chatwoot_note_sent: chatwootNoteSent } }];

async function __salesProdHttpRequest(opts) {
  if (opts && String(opts.url || '').includes('/rest/v1/')) {
    opts = {
      ...opts,
      headers: {
        ...(opts.headers || {}),
        'Accept-Profile': 'sales_prod',
        'Content-Profile': 'sales_prod',
      },
    };
  }
  return this.helpers.httpRequest(opts);
}

// CSE Fase 7 — Calcular score de calificación y persistir
const convId = $json.conv_id;

const SB_URL = ($env.RENOV_SUPABASE_REST_URL || 'http://127.0.0.1:9');
const SB_KEY = $env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET';
const H = { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY };

const calArr = await __salesProdHttpRequest.call(this, {
  method: 'GET',
  url: `${SB_URL}/rest/v1/datos_calificacion?select=*&conversation_id=eq.${convId}`,
  headers: H
});
const calData = Array.isArray(calArr) ? calArr[0] : null;

let score = 0;
const MAX_SCORE = 95;

if (calData) {
  // experiencia_gps (peso 10)
  const gps = (calData.experiencia_gps || '').toUpperCase();
  if (gps === 'SI_ACTUAL') score += 10;
  else if (gps === 'TUVO') score += 7;
  else if (gps === 'NO') score += 4;

  // problema_principal (peso 20) — cualquier respuesta = puntuación completa
  if (calData.problema_principal) score += 20;

  // tomador_decision (peso 25)
  const td = (calData.tomador_decision || '').toUpperCase();
  if (td === 'SI' || td === 'FLOTA') score += 25;
  else if (td === 'NO') score += 10;

  // cantidad_vehiculos (peso 20)
  const qty = parseInt(calData.cantidad_vehiculos) || 1;
  if (qty > 5) score += 20;
  else if (qty >= 2) score += 20;
  else score += 15;

  // urgencia (peso 20)
  const urg = (calData.urgencia || '').toUpperCase();
  if (urg === 'ESTA_SEMANA') score += 20;
  else if (urg === 'ESTE_MES') score += 15;
  else if (urg === 'PROXIMOS_MESES') score += 8;
  else if (urg === 'EXPLORANDO') score += 3;
}

const scoreNorm = Math.min(100, Math.round((score / MAX_SCORE) * 100));

// PATCH datos_calificacion
if (calData) {
  await __salesProdHttpRequest.call(this, {
    method: 'PATCH',
    url: `${SB_URL}/rest/v1/datos_calificacion?conversation_id=eq.${convId}`,
    headers: { ...H, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
    body: JSON.stringify({ score_calificacion: scoreNorm, updated_at: new Date().toISOString() })
  });
}

// PATCH conversaciones
await __salesProdHttpRequest.call(this, {
  method: 'PATCH',
  url: `${SB_URL}/rest/v1/conversaciones?id=eq.${convId}`,
  headers: { ...H, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
  body: JSON.stringify({ score_calificacion: scoreNorm })
});

return [{ json: { ...$json, score_calificacion: scoreNorm, score_raw: score } }];

