parameters.jsCode:
/**
 * [WIN-EVAL] Evaluate Conversation Window
 * ─────────────────────────────────────────────────────────────────────
 * Posición: después de [WIN-CFG] y/o [MEM-1], antes de IF Window Expired?
 *
 * Input esperado (cualquiera disponible):
 *   - window_eval (JSON/JSONB desde Postgres evaluate_conversation_window*)
 *   - last_inbound_message_at / lastInboundMessageAt
 *   - window_minutes, testing_mode (fallback JS)
 *
 * Output:
 *   window_minutes, diff_minutes, window_expired, window_active,
 *   window_log (WINDOW_ACTIVE | WINDOW_EXPIRED),
 *   window_log_detail (WINDOW_MINUTES_USED:N),
 *   use_meta_template (true cuando ventana expirada)
 */
const item = { ...$input.first().json };

function parseEval(raw) {
  if (!raw) return null;
  if (typeof raw === 'string') {
    try { return JSON.parse(raw); } catch (e) { return null; }
  }
  return raw;
}

let evalObj = parseEval(item.window_eval);

function getConversationWindow(ctx = {}) {
  const testingMode = ctx.testing_mode === true
    || ctx.testing_mode === 'true'
    || String(ctx.testing_mode || '').toLowerCase() === 'true';
  if (!testingMode) return 1440;
  const raw = Number(ctx.conversation_window_minutes ?? ctx.window_minutes ?? 3);
  const minutes = Number.isFinite(raw) && raw >= 1 ? raw : 3;
  return Math.min(minutes, 1440);
}

if (!evalObj) {
  const windowMinutes = Number(item.window_minutes) || getConversationWindow(item);

  const lastInboundRaw =
    item.last_inbound_message_at
    || item.lastInboundMessageAt
    || item.mem_last_inbound_message_at
    || null;

  const lastInboundMs = lastInboundRaw ? new Date(lastInboundRaw).getTime() : NaN;
  const hasInbound = Number.isFinite(lastInboundMs);

  const diffMinutes = hasInbound
    ? (Date.now() - lastInboundMs) / 1000 / 60
    : null;

  const windowExpired = !hasInbound || diffMinutes > windowMinutes;
  const windowLog = windowExpired ? 'WINDOW_EXPIRED' : 'WINDOW_ACTIVE';

  evalObj = {
    window_minutes: windowMinutes,
    diff_minutes: diffMinutes == null ? null : Math.round(diffMinutes * 100) / 100,
    window_expired: windowExpired,
    window_active: !windowExpired,
    window_log: windowLog,
    window_log_detail: `WINDOW_MINUTES_USED:${windowMinutes}`,
    last_inbound_at: lastInboundRaw,
  };
}

const cwLabel = evalObj.window_expired ? 'ventana_cerrada' : 'ventana_abierta';
const noteContent = [
  'Conversation window evaluated',
  `Window = ${evalObj.window_minutes} minutes`,
  `Diff = ${evalObj.diff_minutes ?? 'N/A'} minutes`,
  `Status = ${evalObj.window_log}`,
].join('\n');

return [{
  json: {
    ...item,
    window_minutes: evalObj.window_minutes,
    diff_minutes: evalObj.diff_minutes,
    window_expired: evalObj.window_expired,
    window_active: evalObj.window_active,
    window_log: evalObj.window_log,
    window_log_detail: evalObj.window_log_detail,
    lastInboundMessageAt: evalObj.last_inbound_at || item.last_inbound_message_at || null,
    use_meta_template: evalObj.window_expired === true,
    cw_window_label: cwLabel,
    cw_window_labels: [cwLabel],
  },
}];

