/**
 * [WIN-CW] Window Tags & Note — prepara payloads Chatwoot
 */
const item = $input.first().json;

function safeNode(name, path) {
  try {
    const data = $(name).item?.json;
    if (!data) return null;
    return path.split('.').reduce((acc, key) => (acc == null ? acc : acc[key]), data);
  } catch (e) {
    return null;
  }
}

const chatwootConvId =
  item.chatwoot_conv_id
  || item.mem_chatwoot_conv_id
  || safeNode('IF — Usuario respondio?', 'chatwoot_conv_id')
  || safeNode('Edit Fields', 'body.conversation.id')
  || null;

const labels = Array.isArray(item.cw_window_labels)
  ? item.cw_window_labels
  : [item.cw_window_label || (item.window_expired ? 'ventana_cerrada' : 'ventana_abierta')];

const noteContent = item.cw_window_note || [
  'Conversation window evaluated',
  `Window = ${item.window_minutes} minutes`,
  `Diff = ${item.diff_minutes ?? 'N/A'} minutes`,
  `Status = ${item.window_log || 'UNKNOWN'}`,
].join('\n');

if (!chatwootConvId) {
  return [{
    json: {
      ...item,
      cw_window_skip: true,
      window_tag: labels[0],
      reason: 'no_chatwoot_conv_id',
    },
  }];
}

return [{
  json: {
    ...item,
    chatwoot_conv_id: chatwootConvId,
    window_tag: labels[0],
    labels,
    note_content: noteContent,
    cw_tags_payload: JSON.stringify({ labels }),
    cw_note_payload: JSON.stringify({
      content: noteContent,
      message_type: 'outgoing',
      private: true,
    }),
    cw_account_id: 2,
    cw_base_url: 'http://chatwoot:3000',
  },
}];

/**
 * [WIN-MERGE] Restore Context — after Chatwoot side effects, restore eval + inbound body
 * for downstream IF / Detect Type.
 */
const evalData = $('[WIN-EVAL] Evaluate Conversation Window').first().json;

let base = {};
try {
  base = $('Edit Fields').first().json;
} catch (e) {
  base = {};
}

let webhookBody = null;
try {
  webhookBody = $('Webhook').first().json.body;
} catch (e) {
  webhookBody = null;
}

const body = webhookBody || base.body || null;

return [{
  json: {
    ...base,
    ...evalData,
    body,
    window_tag: evalData.cw_window_label || (evalData.window_expired ? 'ventana_cerrada' : 'ventana_abierta'),
  },
}];

/**
 * [CONV-TAG] Build Tags — labels en tiempo real para conversación Chatwoot
 * Preserva ventana_abierta/expired existente y agrega marca (kia/hyundai) + estado
 */
const item = $input.first().json;

// CW conv ID — desde conversation object (Set Contact Context → Get Context Contact)
const chatwootConvId = item.conversation?.id || item.conversation?.display_id || null;

// Preservar labels actuales (incluye ventana_abierta/expired ya aplicado por WIN-CW)
const existingLabels = Array.isArray(item.conversation?.labels) ? item.conversation.labels : [];

// Marca (kia / hyundai)
const marcaRaw = item.contact_context?.additional_attributes?.marca || '';
const marca = marcaRaw.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

// Estado agente (calificacion, cotizacion, interesado, etc.)
const estadoRaw = item.mem_state || '';
const estado = estadoRaw.toLowerCase().replace(/[^a-z0-9_]+/g, '-').replace(/^-|-$/g, '');

// Merge labels sin duplicados
const labelsSet = new Set(existingLabels);
if (marca) labelsSet.add(marca);
if (estado && estado !== 'new-lead' && estado !== 'new_lead') labelsSet.add(estado);

const labels = [...labelsSet];

if (!chatwootConvId) {
  return [{ json: { ...item, conv_tag_skip: true } }];
}

return [{
  json: {
    ...item,
    conv_tag_labels: labels,
    conv_tag_payload: JSON.stringify({ labels }),
