parameters.jsCode:
// CSE — Send Next FAQ: pop siguiente item de faq_queue y enviarlo
// Se dispara cuando el usuario responde durante PRESENTACION_SOLUCION
const convId = $json.conv_id;
const marca = String($json.marca || $json.contact_context?.additional_attributes?.marca || '').toUpperCase();
const serviceName = marca === 'HYUNDAI' ? 'My Hyundai Link' : marca === 'KIA' ? 'Telemetría KIA' : 'servicio de rastreo vehicular';
const now = new Date().toISOString();

const SB_URL = ($env.RENOV_SUPABASE_REST_URL || 'http://127.0.0.1:9');
const SB_KEY = $env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET';
const H_SB = { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' };

const META_TOKEN = $env.RENOV_META_ACCESS_TOKEN || $env.META_ACCESS_TOKEN || 'RENOV_DEV_TOKEN_NOT_SET';
const META_PHONE_ID = $env.RENOV_META_PHONE_NUMBER_ID || 'RENOV_DEV_PHONE_ID_NOT_SET';

const clientPhone = (
  $json.contact_context?.phone_number ||
  $('Edit Fields').first().json.body?.conversation?.meta?.sender?.phone_number ||
  ''
).replace(/^\+/, '');

const urlBase = $('Edit Fields').first().json.URL_OMNICEM;
const token   = $('Edit Fields').first().json.TOKEN || $env.RENOV_CHATWOOT_API_TOKEN || '';
const accountId      = $('Edit Fields').first().json.account_id;
const chatwootConvId = $('Edit Fields').first().json.conversation_display_id;

const httpReq = this.helpers.httpRequest.bind(this);
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));

async function sendBlock(text) {
  const promises = [];
  if (urlBase && token && accountId && chatwootConvId) {
    promises.push(
      httpReq({
        method: 'POST',
        url: `http://${urlBase}/api/v1/accounts/${accountId}/conversations/${chatwootConvId}/messages`,
        headers: { 'api_access_token': token, 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: text, message_type: 'outgoing', private: false })
      }).catch(() => {})
    );
  }
  if (clientPhone) {
    promises.push(
      httpReq({
        method: 'POST',
        url: `https://graph.facebook.com/v23.0/${META_PHONE_ID}/messages`,
        headers: { 'Authorization': 'Bearer ' + META_TOKEN, 'Content-Type': 'application/json' },
        body: JSON.stringify({ messaging_product: 'whatsapp', to: clientPhone, type: 'text', text: { body: text } })
      }).catch(() => {})
    );
  }
  await Promise.all(promises);
}

// 1. Cargar faq_queue de datos_calificacion
const dcRows = await httpReq({
  method: 'GET',
  url: `${SB_URL}/rest/v1/datos_calificacion?conversacion_id=eq.${convId}&select=faq_queue,faq_shown_count`,
  headers: { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY }
});

const dc = (dcRows && dcRows.length > 0) ? dcRows[0] : null;
const queue = (dc && Array.isArray(dc.faq_queue)) ? dc.faq_queue : [];
const shownCount = (dc && dc.faq_shown_count) || 0;

if (queue.length === 0) {
  // Cola vacía — enviar CTA de cierre y no bloquear el flujo normal de la AI
  return [{ json: { ...$json, cse_next_faq: 'queue_empty', wa_message: '', wa_to: clientPhone } }];
}

// 2. Pop primer item de la cola
const nextItem = queue[0];
const remainingQueue = queue.slice(1);

// 3. Primero, enviar la respuesta de la AI si existe (el agente pudo haber respondido algo)
// Luego enviar el siguiente item FAQ
await delay(1000);
await sendBlock(`*${nextItem.titulo}*\n${nextItem.contenido}`);

// 4. Si quedan más items, dar pista
if (remainingQueue.length > 0) {
  await delay(1500);
  await sendBlock(`Tengo ${remainingQueue.length} beneficio${remainingQueue.length > 1 ? 's' : ''} más que compartirle. ¿Le gustaría conocerlos?`);
} else {
  // Último item enviado — CTA de cierre
  await delay(1500);
  await sendBlock(`Esos son todos los beneficios principales de *${serviceName}* para usted. ¿Tiene alguna pregunta o le gustaría conocer los valores disponibles? 😊`);
}

// 5. Actualizar datos_calificacion
await httpReq({
  method: 'PATCH',
  url: `${SB_URL}/rest/v1/datos_calificacion?conversacion_id=eq.${convId}`,
  headers: { ...H_SB, 'Prefer': 'return=minimal' },
  body: JSON.stringify({ faq_queue: remainingQueue, faq_shown_count: shownCount + 1 })
});

// Registrar evento
await httpReq({
  method: 'POST',
  url: `${SB_URL}/rest/v1/eventos_conversacion`,
  headers: { ...H_SB, 'Prefer': 'return=minimal' },
  body: JSON.stringify({
    conversation_id: convId,
    tipo_evento: 'FAQ_ITEM_ENVIADO',
    datos_evento: {
      titulo: nextItem.titulo,
      shown_count: shownCount + 1,
      remaining: remainingQueue.length
    }
  })
});

// wa_message vacío para que el nodo downstream no re-envíe
return [{ json: { ...$json, cse_next_faq: 'item_sent', faq_shown: shownCount + 1, faq_remaining: remainingQueue.length, wa_message: '', wa_to: clientPhone } }];

async function __salesProdHttpRequest(opts) {
  if (opts && String(opts.url || '').includes('/rest/v1/')) {
    opts = {
      ...opts,
      headers: {
        ...(opts.headers || {}),
        'Accept-Profile': 'sales_prod',
        'Content-Profile': 'sales_prod',
      },
    };
  }
  return this.helpers.httpRequest(opts);
}

const item = $input.first().json;
const body = $('Edit Fields').first().json.body || {};

function normalizeKey(s) {
  return String(s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function pickMessage(body) {
  return body.entry?.[0]?.changes?.[0]?.value?.messages?.[0]
    || body.conversation?.messages?.[0]
    || body.messages?.[0]
    || body;
}

const msg = pickMessage(body);
const interactive = msg.interactive || {};
const buttonReply = interactive.button_reply || {};
const listReply = interactive.list_reply || {};

const rawContent = String(item.concat_message || body.content || msg.text?.body || '');
function parseBlobField(txt, field) {
  const m = new RegExp('^' + field + '\s*:\s*(.*)$', 'im').exec(String(txt || ''));
  const v = m ? String(m[1] || '').trim() : '';
  return (v && v !== '-') ? v : '';
}

const blobAction = parseBlobField(rawContent, 'button_action');
const blobModel = parseBlobField(rawContent, 'model');
const blobText = parseBlobField(rawContent, 'button_text');
const blobPayload = parseBlobField(rawContent, 'button_payload');
const looksLikeButtonBlob = Boolean(blobPayload || blobText || /^button_action\s*:/im.test(rawContent));

const structuredPayload = buttonReply.id
  || listReply.id
  || body.content_attributes?.button_reply?.id
  || body.content_attributes?.submitted_values?.id
  || msg.button?.payload
  || null;
const structuredTitle = buttonReply.title
  || listReply.title
  || body.content_attributes?.button_reply?.title
  || body.content_attributes?.submitted_values?.title
  || msg.button?.text
  || null;

const buttonPayload = structuredPayload || blobPayload || null;
const buttonHumanText = structuredTitle || blobText || null;
const buttonId = buttonPayload;
const buttonTitle = buttonHumanText || buttonPayload || null;
const buttonKey = normalizeKey(buttonPayload || buttonHumanText);

const waMessageId = msg.id || body.source_id || body.message_id || body.id || null;
const replyToMessageId = msg.context?.id || body.content_attributes?.in_reply_to || null;
const phone = item.phone || body.contact?.phone_number || body.conversation?.meta?.sender?.phone_number || body.from || '';
const currentState = item.conversation_state || $json.mem_state || 'NEW_LEAD';
const convId = item.conversation_id || $json.conv_id || null;

const BUTTON_RULES = {
  si_quiero_saber_mas: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  si_enviarme_informacion: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  si_quiero_conocerlas: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  si_enviarlo: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  si_muestrame_las_opciones: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  si_compartir_guia: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  si_cuentame_mas: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  si_enviar_informacion: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  cuentame_mas: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  quiero_descubrirlas: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  deseo_mas_info: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  deseo_mas_informacion: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  contactar_a_un_asesor: { kind: 'HANDOFF', expectedStates: ['CONTACTED_3','QUOTED','PLAN_SELECTED'] },
  si_quiero_contratar: { kind: 'HANDOFF', expectedStates: ['PLAN_SELECTED'] },
  enviar_propuesta: { kind: 'PROPOSAL_CONFIRMATION', expectedStates: ['PLAN_SELECTED'] },
  send_proposal: { kind: 'PROPOSAL_CONFIRMATION', expectedStates: ['PLAN_SELECTED'] },
  revisar_otro_plan: { kind: 'PROPOSAL_CONFIRMATION', expectedStates: ['PLAN_SELECTED'] },
  tengo_una_duda: { kind: 'PROPOSAL_CONFIRMATION', expectedStates: ['PLAN_SELECTED'] },
  gancho_q2_seguridad: { kind: 'TOPIC_SELECTION', expectedStates: ['ENGAGED','VALUE_PRESENTED'] },
  gancho_q2_control: { kind: 'TOPIC_SELECTION', expectedStates: ['ENGAGED','VALUE_PRESENTED'] },
  gancho_q2_planes: { kind: 'TOPIC_SELECTION', expectedStates: ['ENGAGED','VALUE_PRESENTED'] },
  no_por_el_momento: { kind: 'NEGATIVE', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  gancho_si_gancho_q1_neutral: { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  gancho_no_gancho_q1_neutral: { kind: 'NEGATIVE', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] },
  no_es_de_mi_interes: { kind: 'NEGATIVE', expectedStates: ['CONTACTED_3'] },
  auto_kia: { kind: 'VEHICLE_SELECTION', expectedStates: ['VEHICLE_SELECTION','NEW_LEAD','CONTACTED_1'] },
  auto_hyundai: { kind: 'VEHICLE_SELECTION', expectedStates: ['VEHICLE_SELECTION','NEW_LEAD','CONTACTED_1'] },
  auto_otra: { kind: 'VEHICLE_SELECTION', expectedStates: ['VEHICLE_SELECTION','NEW_LEAD','CONTACTED_1'] },
  moto: { kind: 'OUT_OF_SCOPE_OR_GENERIC', expectedStates: ['VEHICLE_SELECTION','NEW_LEAD','CONTACTED_1'] },
  flota: { kind: 'FLEET', expectedStates: ['VEHICLE_SELECTION','NEW_LEAD','CONTACTED_1'] },
};

const dynamicGanchoInterestRule = /^gancho_si_(?:gancho_v\d+|gancho_q1_neutral)$/.test(buttonKey)
  ? { kind: 'INTEREST', expectedStates: ['CONTACTED_1','CONTACTED_2','CONTACTED_3','NEW_LEAD','ENGAGED','VALUE_PRESENTED'] }
  : null;
function canonicalPlanActionFromKey(key) {
  const m = /^plan_([a-z0-9_]+)_(12|24|36)m$/.exec(String(key || ''));
  return m ? 'PLAN_' + m[1].toUpperCase() + '_' + m[2] + 'M' : null;
}
const dynamicPlanAction = canonicalPlanActionFromKey(buttonKey);
const dynamicPlanRule = dynamicPlanAction
  ? { kind: dynamicPlanAction, expectedStates: ['QUOTED','VALUE_PRESENTED','HANDOFF_HUMAN'] }
  : null;
const rule = BUTTON_RULES[buttonKey] || dynamicGanchoInterestRule || dynamicPlanRule || null;
const resolvedButtonAction = blobAction || rule?.kind || 'UNKNOWN_BUTTON';
const assistedPlanClaim = String(currentState || '').toUpperCase() === 'HANDOFF_HUMAN' && Boolean(dynamicPlanAction);
let assistedClaimToken = null;

function cleanModelValue(value) {
  const v = String(value || '').trim();
  return (v && v !== '-') ? v : '';
}

async function resolveButtonModel() {
  const direct = cleanModelValue(blobModel)
    || cleanModelValue(item.modelo)
    || cleanModelValue($json.modelo)
    || cleanModelValue($json.contact_context?.additional_attributes?.modelo)
    || cleanModelValue($json.contact_context?.custom_attributes?.modelo)
    || cleanModelValue($json.conversation?.custom_attributes?.modelo)
    || cleanModelValue(body.conversation?.custom_attributes?.modelo)
    || cleanModelValue(body.conversation?.meta?.sender?.additional_attributes?.modelo);
  if (direct) return direct;

  try {
    const cwId = parseInt(body.conversation?.id || body.conversation?.display_id || item.chatwoot_conv_id || item.conversation_id || 0, 10) || 0;
    if (!cwId) return '';
    const rows = await __salesProdHttpRequest.call(this, {
      method: 'GET',
      url: ($env.RENOV_SUPABASE_REST_URL || 'http://127.0.0.1:9') + '/rest/v1/conversation_context?chatwoot_conv_id=eq.' + cwId + '&select=active_model&limit=1',
      headers: { apikey: $env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET', Authorization: 'Bearer ' + ($env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET') }
    });
    const activeModel = Array.isArray(rows) ? rows[0]?.active_model : null;
    if (cleanModelValue(activeModel)) return cleanModelValue(activeModel);
  } catch(e) {}
  return '';
}

const resolvedButtonModel = await resolveButtonModel();
const normalizedButtonContent = looksLikeButtonBlob
  ? [
      'button_action: ' + resolvedButtonAction,
      'model: ' + (resolvedButtonModel || '-'),
      'button_text: ' + (buttonHumanText || '-'),
      'button_payload: ' + (buttonPayload || '-')
    ].join('\n')
  : rawContent;

const isButton = Boolean(
  buttonReply.id || buttonReply.title ||
  listReply.id || listReply.title ||
  body.content_attributes?.button_reply ||
  body.content_attributes?.submitted_values ||
  msg.button || looksLikeButtonBlob
);

if (!isButton) {
  return [{ json: { ...item, button_guard_should_process: true, button_guard_reason: 'not_button' } }];
}

let shouldProcess = true;
let reason = 'claimed';
try {
  const resp = await __salesProdHttpRequest.call(this, {
    method: 'POST',
    url: ($env.RENOV_SUPABASE_REST_URL || 'http://127.0.0.1:9') + '/rest/v1/rpc/' + (assistedPlanClaim ? 'claim_assisted_handoff_plan_interaction' : 'claim_whatsapp_button_interaction'),
    headers: {
      apikey: $env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET',
      Authorization: 'Bearer ' + ($env.RENOV_SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY || 'RENOV_DEV_SUPABASE_KEY_NOT_SET'),
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      p_phone: phone,
      p_conversation_id: convId,
      p_wa_message_id: waMessageId,
      p_reply_to_message_id: replyToMessageId,
      p_button_id: buttonId,
      p_button_title: buttonTitle,
      p_button_key: buttonKey,
      p_expected_states: rule?.expectedStates || [],
      p_current_state: currentState
    })
  });
  const row = Array.isArray(resp) ? resp[0] : resp;
  reason = row?.reason || reason;
  assistedClaimToken = row?.claim_token_out || row?.claim_token || null;
  // V111: the RPC owns duplicate, stale, terminal and consumed-menu decisions.
  shouldProcess = assistedPlanClaim
    ? row?.should_process === true && Boolean(assistedClaimToken)
    : row?.should_process !== false;
  if (assistedPlanClaim && row?.should_process === true && !assistedClaimToken) {
    reason = 'assisted_claim_missing_token';
  }
} catch (e) {
  // Normal messages remain fail-open, but assisted plan claims must never bypass V136.
  shouldProcess = !assistedPlanClaim;
  reason = (assistedPlanClaim ? 'assisted_claim_error_fail_closed:' : 'claim_error_fail_open:') + (e.message || String(e)).slice(0, 120);
}

return [{
  json: {
    ...item,
    button_guard_is_button: true,
    button_guard_should_process: shouldProcess,
    button_guard_reason: reason,
    button_guard_key: buttonKey,
    button_guard_kind: resolvedButtonAction,
    button_guard_action: resolvedButtonAction,
    button_guard_model: resolvedButtonModel || null,
    button_guard_payload: buttonPayload,
    button_guard_text: buttonHumanText,
    button_guard_normalized_content: normalizedButtonContent,
    button_guard_current_state: currentState,
    button_guard_wa_message_id: waMessageId,
    button_guard_claim_token: assistedClaimToken,
    button_guard_reply_to_message_id: replyToMessageId,
    button_guard_title: buttonTitle,
  }
}];

const item = $input.first().json;
const reason = String(item.button_guard_reason || '').toLowerCase();
const state = String(item.button_guard_current_state || item.conversation_state || item.next_state || '').toUpperCase();
const silentReasons = new Set([
  'duplicate_message_id',
  'duplicate_race',
  'button_already_consumed',
  'interaction_already_consumed',
  'topic_action_already_selected',
  'stale_state',
  'stale_interaction_type',
  'missing_wa_message_id',
  'no_active_topic_interaction',
]);

const assistedPlanAttempt = state === 'HANDOFF_HUMAN' && /^plan_/.test(String(item.button_guard_key || '').toLowerCase());
