async function resolveContext() {
  let convId = item.conv_id || item.conversation_id || null;
  let phone = item.contact_context?.phone_number || item.phone || item.telefono_1 || '';
  let chatwootConvId = item.chatwoot_conv_id || item.conversation?.display_id || item.conversation?.id || null;
  try {
    const ef = $('Edit Fields').first().json || {};
    const body = ef.body || {};
    chatwootConvId = chatwootConvId || ef.conversation_display_id || body.conversation?.display_id || body.conversation?.id || null;
    phone = phone || body.conversation?.meta?.sender?.phone_number || body.contact?.phone_number || body.from || '';
  } catch (e) {}

  if (!convId && chatwootConvId) {
    try {
      const rows = await __salesProdHttpRequest.call(this, {
        method: 'GET',
        url: SB_URL + '/rest/v1/conversaciones?chatwoot_conv_id=eq.' + encodeURIComponent(chatwootConvId) + '&select=id&limit=1',
        headers: H_SB
      });
      if (Array.isArray(rows) && rows[0]?.id) convId = rows[0].id;
    } catch (e) {}
  }

  return { convId, phone: cleanPhone(phone), chatwootConvId };
}

async function resolveMarcaFromDb(ctx) {
  if (resolvedMarca) return resolvedMarca;
  const filters = [];
  if (ctx?.convId) filters.push('id=eq.' + encodeURIComponent(ctx.convId));
  if (ctx?.chatwootConvId) filters.push('chatwoot_conv_id=eq.' + encodeURIComponent(ctx.chatwootConvId));
  for (const filter of filters) {
    try {
      const rows = await __salesProdHttpRequest.call(this, {
        method: 'GET',
        url: SB_URL + '/rest/v1/conversaciones?' + filter + '&select=marca&limit=1',
        headers: H_SB
      });
      const m = String(Array.isArray(rows) && rows[0]?.marca || '').trim().toUpperCase();
      if (m === 'KIA' || m === 'HYUNDAI') {
        resolvedMarca = m;
        serviceName = serviceNameForMarca(m);
        return m;
      }
    } catch (e) {}
  }
  return '';
}

