async function setCanonicalStateAndMemory(ctx, nextState, memoryPatch = {}, source = 'cse_deterministic') {
  const now = new Date().toISOString();
  const result = { conversation_updated: false, memory_updated: false, errors: [] };
  if (!ctx.convId) {
    result.errors.push('missing_conv_id');
    return result;
  }
  try {
    const rows = await __salesProdHttpRequest.call(this, {
      method: 'POST',
      url: SB_URL + '/rest/v1/rpc/set_conversation_state',
      headers: { ...H_SB, Prefer: 'return=representation' },
      body: { p_conversation_id: ctx.convId, p_new_state: nextState, p_source: source, p_metadata: { button_key: key } },
      json: true
    });
    const stateResult = Array.isArray(rows) ? rows[0] : rows;
    result.conversation_updated = stateResult?.changed === true || stateResult?.reason === 'unchanged' || ['no_change','unchanged'].includes(stateResult?.reason);
    if (!result.conversation_updated) result.errors.push('state:' + (stateResult?.reason || 'unknown'));
  } catch (e) {
    result.errors.push('state:' + String(e.message || e).slice(0, 160));
  }
  try {
    await __salesProdHttpRequest.call(this, {
      method: 'PATCH',
      url: SB_URL + '/rest/v1/lead_memory?conversation_id=eq.' + encodeURIComponent(ctx.convId),
      headers: { ...H_SB, Prefer: 'return=minimal' },
      body: JSON.stringify({ conversation_state: nextState, updated_at: now, ...memoryPatch })
    });
    result.memory_updated = true;
  } catch (e) {
    result.errors.push('memory:' + String(e.message || e).slice(0, 160));
  }
  return result;
}

