async function patchPending(ctx) {
  const now = new Date().toISOString();
  const result = { conversation_updated: false, memory_updated: false, errors: [] };
  if (!ctx.convId) {
    result.errors.push('missing_conv_id');
    return result;
  }
  try {
    const fsmFinalState = reason.final_state === 'CONTACTAR' ? 'LOST' : reason.final_state;
    const stateRows = await __salesProdHttpRequest.call(this, {
      method: 'POST',
