        p_metadata: { final_state: reason.final_state, loss_reason_code: reason.code, observacion: reason.observacion }
      },
      json: true
    });
    const stateResult = Array.isArray(stateRows) ? stateRows[0] : stateRows;
    const stateOk = stateResult?.changed === true || ['no_change','unchanged'].includes(stateResult?.reason);
    if (!stateOk) {
      result.errors.push('state_transition:' + JSON.stringify(stateResult).slice(0, 160));
