          loss_reason_date: now,
          final_state: reason.final_state,
          ultima_respuesta_at: now
        },
        json: true
      });
      result.conversation_updated = Array.isArray(rows) && rows.some(row => row.loss_reason_code === reason.code);
      if (!result.conversation_updated) result.errors.push('conversation_not_updated');
    }
  } catch (e) {
    result.errors.push('conversation:' + String(e.message || e).slice(0, 160));
  }
  try {
    await __salesProdHttpRequest.call(this, {
      method: 'PATCH',
      url: SB_URL + '/rest/v1/lead_memory?conversation_id=eq.' + encodeURIComponent(ctx.convId),
