function normalizeAttachmentUrl(raw) {
  const value = String(raw || '').trim();
  if (!value) return '';
  if (/^url_del_pdf_de_propuesta_kia$/i.test(value)) return 'https://codercase.com/img/QL/PROPUESTA_COMERCIAL_KIA.pdf';
  if (/^url_del_pdf_de_propuesta_hyundai$/i.test(value)) return 'https://codercase.com/img/QL/PROPUESTA_COMERCIAL_HYUNDAI.pdf';
  return value;
}

function isPlaceholder(url) {
  const value = String(url || '').trim();
  return !/^https?:\/\//i.test(value) || /example\.(com|org|net)|localhost|127\.0\.0\.1/i.test(value);
}

function isSmsOnlyUrl(url) {
