const previousStatus = lastStatusMatch ? lastStatusMatch[1] : null;
const shouldPost = Boolean(currentStatus) && previousStatus !== currentStatus;

return [{
  json: {
    ...prep,
    window_note_should_post: shouldPost,
    window_note_previous_status: previousStatus,
    window_note_current_status: currentStatus || null,
    window_note_reason: shouldPost
      ? (previousStatus ? 'window_status_changed' : 'no_previous_window_note')
      : 'same_window_status',
  },
}];
